/* ROBOQUEST engine bundle — GENERATED by scripts/robo/make_react.py. DO NOT EDIT.

   Classic script (not an ES module): executed via <script> injection so the

   engine behaves byte-identically to the single-file roboquest.html build. */

/* ===== engine.js ===== */
'use strict';
/* ================= ROBOQUEST CORE ENGINE =================
   Data layer (localStorage), auth, gamification, router, UI kit */
window.RQ = { views:{}, DATA:{ LESSONS:{}, QUESTIONS:[], MISSIONS:[], CHALLENGES:[], PSEUDO:[], DAILY:[] } };

/* ---------- safe storage (survives sandboxed previews & blocked storage) ----------
   Every operation is guarded: storage may pass the boot-time probe but start
   failing later (quota, permissions, sandbox restrictions). On any failure the
   shim degrades to an in-memory store for that call and stays there. */
RQ.store=(function(){
  const mem={};
  let real=null, mode='local';
  try{ const k='__rq_probe__'; localStorage.setItem(k,'1'); localStorage.getItem(k); localStorage.removeItem(k);
    real={ get:k=>localStorage.getItem(k), set:(k,v)=>localStorage.setItem(k,String(v)), del:k=>localStorage.removeItem(k) };
  }catch(e){ real=null; mode='memory'; }
  function via(fn, memFn){
    if(real){ try{ return fn(real); }catch(e){ real=null; mode='memory'; } }
    return memFn();
  }
  return {
    get:k=>via(r=>r.get(k), ()=>(k in mem? mem[k]:null)),
    set:(k,v)=>via(r=>r.set(k,v), ()=>{ mem[k]=String(v); }),
    del:k=>via(r=>r.del(k), ()=>{ delete mem[k]; }),
    get mode(){ return mode; }
  };
})();
RQ.sessionStore=(function(){
  const mem={};
  let real=null;
  try{ const k='__rq_probe__'; sessionStorage.setItem(k,'1'); sessionStorage.getItem(k); sessionStorage.removeItem(k);
    real={ get:k=>sessionStorage.getItem(k), set:(k,v)=>sessionStorage.setItem(k,String(v)), del:k=>sessionStorage.removeItem(k) };
  }catch(e){ real=null; }
  function via(fn, memFn){
    if(real){ try{ return fn(real); }catch(e){ real=null; } }
    return memFn();
  }
  return {
    get:k=>via(r=>r.get(k), ()=>(k in mem? mem[k]:null)),
    set:(k,v)=>via(r=>r.set(k,v), ()=>{ mem[k]=String(v); }),
    del:k=>via(r=>r.del(k), ()=>{ delete mem[k]; })
  };
})();

/* ---------- constants ---------- */
RQ.YEARS = [8,9,10,11];
RQ.YEAR_META = {
  8:{name:'Rookie Coders', color:'#26d9f2', tag:'Beginner programming & robotics'},
  9:{name:'Code Explorers', color:'#4f7cff', tag:'Developing problem-solvers'},
  10:{name:'Python Engineers', color:'#a78bfa', tag:'Intermediate Python & robotics'},
  11:{name:'Robotics Masters', color:'#f472b6', tag:'Advanced algorithms & autonomy'}
};
RQ.LEVELS = [
  {lvl:1,name:'Code Rookie',xp:0},{lvl:2,name:'Logic Explorer',xp:250},
  {lvl:3,name:'Loop Specialist',xp:600},{lvl:4,name:'Python Builder',xp:1000},
  {lvl:5,name:'Robotics Designer',xp:1500},{lvl:6,name:'Algorithm Expert',xp:2200},
  {lvl:7,name:'Automation Engineer',xp:3000},{lvl:8,name:'Robotics Master',xp:4000}
];
RQ.TEACHER_INVITE_CODE = 'ROBOSTAFF';
RQ.AVATAR_COLORS = ['#26d9f2','#4f7cff','#a78bfa','#f472b6','#34d399','#fbbf24','#fb7185','#22d3ee'];

/* ---------- tiny helpers ---------- */
RQ.esc = s => String(s==null?'':s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
RQ.shuffle = a => { a=a.slice(); for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];} return a; };
RQ.hashPick = (str,n) => { let h=0; for(let i=0;i<str.length;i++){h=(h*31+str.charCodeAt(i))>>>0;} return h%n; };
/* show/hide password fields (eye toggle on every auth form) */
RQ.pwEye = (id,btn) => { const inp=document.getElementById(id); if(!inp) return;
  const show=inp.type==='password'; inp.type=show?'text':'password';
  btn.textContent=show?'🙈 Hide':'👁 Show'; };
RQ.todayKey = () => { const d=new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); };
RQ.weekKey = () => { const d=new Date(), o=new Date(d.getFullYear(),0,1);
  return d.getFullYear()+'-W'+String(Math.ceil((((d-o)/864e5)+o.getDay()+1)/7)).padStart(2,'0'); };
RQ.daysSince = ts => Math.floor((Date.now()-ts)/864e5);

/* ---------- database (localStorage) ---------- */
RQ.DB = {
  KEY:'roboquest_db_v1', data:null,
  load(){
    try{ const raw=RQ.store.get(this.KEY); if(raw) this.data=JSON.parse(raw); }catch(e){ this.data=null; }
    if(!this.data || this.data.v!==1){ this.data=this.seed(); this.save(); }
    return this.data;
  },
  save(){
    try{ RQ.store.set(this.KEY, JSON.stringify(this.data)); }
    catch(e){ RQ.toast('Storage limit reached — export a backup from your profile!','bad'); }
  },
  nextId(){ return this.data.settings.nextId++; },
  uid(p){ return (p||'id')+Date.now().toString(36)+Math.random().toString(36).slice(2,7); },
  export(){
    const blob=new Blob([JSON.stringify(this.data,null,1)],{type:'application/json'});
    const a=document.createElement('a'); a.href=URL.createObjectURL(blob);
    a.download='roboquest-backup-'+RQ.todayKey()+'.json'; a.click();
    setTimeout(()=>URL.revokeObjectURL(a.href),4000);
  },
  import(file, cb){
    const r=new FileReader();
    r.onload=()=>{ try{ const d=JSON.parse(r.result);
        if(!d || d.v!==1 || !Array.isArray(d.users)) throw new Error('Not a ROBOQUEST backup');
        this.data=d; this.save(); cb(null);
      }catch(err){ cb(err.message||'Invalid file'); } };
    r.readAsText(file);
  },
  seed(){
    const now=Date.now();
    const db={ v:1, settings:{ nextId:1, leaderboardPublic:true },
      users:[], classes:[], memberships:[], assignments:[],
      customQuestions:[], customLessons:[], customChallenges:[], customMissions:[],
      progress:{}, attempts:[], quizAttempts:[], missionAttempts:[], feedback:[] };
    // demo leaderboard students (clearly marked; removable by teacher)
    const demo=[['NovaByte','Nova Byte',9,1540],['PixelPiper','Pixel Piper',8,1120],
      ['QuantumQuinn','Quinn A.',11,2380],['ServoSam','Sam R.',10,1890],
      ['GearGrace','Grace L.',8,760],['LogicLeo','Leo M.',10,2210]];
    demo.forEach((d,i)=>{
      const id='demo'+(i+1);
      db.users.push({id, role:'student', username:'demo_'+d[0].toLowerCase(), name:d[1],
        year:d[2], avatar:{color:RQ.AVATAR_COLORS[i%8]}, demo:true, createdAt:now});
      db.progress[id]={ stats:{xp:d[3], coins:Math.round(d[3]/2), lessonsDone:0, missionsDone:0, quizRuns:0,
        perfect:0, codeRuns:0, blockRuns:0, pyRuns:0, dailyDone:0, stars:0},
        streak:{count:2,last:RQ.todayKey()}, xpWeek:{key:RQ.weekKey(),amount:Math.round(d[3]/6)},
        lessons:{}, missions:{}, quizzes:{}, badges:[], lastActive:now-864e5*(i%5) };
    });
    return db;
  }
};

/* ---------- auth ---------- */
RQ.Auth = {
  session:null,
  async hash(pw, salt){
    const msg = salt+':'+pw;
    try{
      if(window.crypto && crypto.subtle){
        const buf=await crypto.subtle.digest('SHA-256', new TextEncoder().encode(msg));
        return 's256-'+[...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('');
      }
    }catch(e){}
    // deterministic fallback (local demo storage only)
    let h1=0x811c9dc5,h2=0x1505; for(let i=0;i<msg.length;i++){
      h1=(h1^msg.charCodeAt(i))*16777619>>>0; h2=(h2*33+msg.charCodeAt(i))>>>0; }
    return 'fb-'+h1.toString(16)+h2.toString(16);
  },
  restore(){ try{ this.session=JSON.parse(RQ.store.get('rq_session')||'null'); }catch(e){ this.session=null; } },
  setSession(s){ this.session=s; if(s) RQ.store.set('rq_session',JSON.stringify(s)); else RQ.store.del('rq_session'); },
  user(){ return this.session ? RQ.DB.data.users.find(u=>u.id===this.session.userId) : null; },
  async registerStudent({name,username,password,year,avatar,classCode,track,kidsLevel}){
    const db=RQ.DB.data;
    username=String(username||'').trim().toLowerCase();
    name=String(name||'').trim();
    if(name.length<2) throw new Error('Please enter your display name (2+ characters).');
    if(!/^[a-z0-9_]{3,16}$/.test(username)) throw new Error('Username must be 3-16 letters, numbers or underscores.');
    if((password||'').length<6) throw new Error('Password must be at least 6 characters.');
    const kids = track==='kids';
    if(kids){ if(![1,2,3].includes(Number(kidsLevel))) throw new Error('Please choose your age group.'); }
    else if(!RQ.YEARS.includes(Number(year))) throw new Error('Please choose your year group.');
    if(db.users.some(u=>u.username===username)) throw new Error('That username is already taken.');
    const salt=RQ.DB.uid('s'); const passHash=await this.hash(password,salt);
    const u={ id:RQ.DB.uid('u'), role:'student', username, name,
      year: kids? null : Number(year),
      track: kids? 'kids':'academy',
      kidsLevel: kids? Number(kidsLevel):undefined,
      passHash, salt, avatar: avatar||{color:RQ.AVATAR_COLORS[0]}, demo:false, createdAt:Date.now() };
    db.users.push(u);
    db.progress[u.id]=RQ.newProgress();
    let joined=null;
    if(classCode){ const r=this.joinClass(u.id,String(classCode).trim().toUpperCase()); if(r) joined=r.className; }
    RQ.DB.save(); return {user:u, joined};
  },
  async registerTeacher({name,username,password,invite}){
    const db=RQ.DB.data;
    if(String(invite||'').trim().toUpperCase()!==RQ.TEACHER_INVITE_CODE)
      throw new Error('Invalid teacher invite code — ask your school admin.');
    username=String(username||'').trim().toLowerCase();
    if(!/^[a-z0-9_]{3,20}$/.test(username)) throw new Error('Username must be 3-20 letters, numbers or underscores.');
    if((password||'').length<8) throw new Error('Teacher password must be at least 8 characters.');
    if(db.users.some(u=>u.username===username)) throw new Error('That username is already taken.');
    const salt=RQ.DB.uid('s'); const passHash=await this.hash(password,salt);
    const u={ id:RQ.DB.uid('t'), role:'teacher', username, name:String(name||'Teacher').trim()||'Teacher', passHash, salt, avatar:{color:'#fbbf24'}, createdAt:Date.now() };
    db.users.push(u); RQ.DB.save(); return u;
  },
  async login(username,password){
    const db=RQ.DB.data;
    const u=db.users.find(x=>x.username===String(username||'').trim().toLowerCase());
    if(!u) throw new Error('No account found with that username.');
    if(!u.passHash) throw new Error('This demo account has no password. Try registering your own account.');
    const h=await this.hash(password||'',u.salt||'');
    if(h!==u.passHash) throw new Error('Incorrect password.');
    this.setSession({userId:u.id, role:u.role, at:Date.now()});
    return u;
  },
  logout(){ this.setSession(null); RQ.go('welcome'); },
  joinClass(studentId, code){
    const db=RQ.DB.data;
    const cls=db.classes.find(c=>c.code===code);
    if(!cls) return null;
    if(!db.memberships.some(m=>m.classId===cls.id && m.studentId===studentId))
      db.memberships.push({id:RQ.DB.uid('m'), classId:cls.id, studentId, joinedAt:Date.now()});
    return cls;
  },
  studentClass(studentId){ const db=RQ.DB.data; const m=db.memberships.find(m=>m.studentId===studentId);
    return m ? db.classes.find(c=>c.id===m.classId) : null; },
  teacherClasses(teacherId){ const db=RQ.DB.data; return db.classes.filter(c=>c.teacherId===teacherId); },
  classStudents(classId){ const db=RQ.DB.data;
    return db.memberships.filter(m=>m.classId===classId)
      .map(m=>db.users.find(u=>u.id===m.studentId)).filter(Boolean); }
};
RQ.newProgress = () => ({ stats:{xp:0,coins:50,lessonsDone:0,missionsDone:0,quizRuns:0,perfect:0,
    codeRuns:0,blockRuns:0,pyRuns:0,dailyDone:0,stars:0},
  streak:{count:0,last:null}, xpWeek:{key:RQ.weekKey(),amount:0},
  lessons:{}, missions:{}, quizzes:{}, badges:[], lastActive:Date.now() });

/* ---------- gamification ---------- */
RQ.Game = {
  levelOf(xp){ let cur=RQ.LEVELS[0]; for(const L of RQ.LEVELS) if(xp>=L.xp) cur=L; return cur; },
  nextLevel(xp){ return RQ.LEVELS.find(L=>L.xp>xp) || null; },
  award(uid, xp, coins, reason, opts){
    const db=RQ.DB.data; const p=db.progress[uid]; if(!p) return;
    opts=opts||{};
    p.stats.xp+=xp; p.stats.coins+=(coins||0);
    if(p.xpWeek.key!==RQ.weekKey()) p.xpWeek={key:RQ.weekKey(),amount:0};
    p.xpWeek.amount+=xp;
    const before=this.levelOf(p.stats.xp-xp).lvl, after=this.levelOf(p.stats.xp).lvl;
    // streak
    const today=RQ.todayKey(), yest=new Date(Date.now()-864e5).toISOString().slice(0,10);
    if(p.streak.last!==today){ p.streak.count=(p.streak.last===yest)?p.streak.count+1:1; p.streak.last=today; }
    p.lastActive=Date.now();
    RQ.DB.save();
    RQ.toast('+'+xp+' XP'+(coins?'  +'+coins+' coins':'')+' — '+reason,'xp');
    RQ.refreshHUD();
    if(after>before){
      const L=RQ.LEVELS[after-1];
      RQ.modal(`<div class="reward-pop"><div class="big-ico">🚀</div>
        <h2 style="margin:10px 0">LEVEL UP!</h2>
        <p class="muted">You reached <b style="color:var(--pu)">Level ${L.lvl} — ${L.name}</b></p>
        <p class="dim small mt-s">Keep the streak going, engineer.</p>
        <button class="btn primary mt" onclick="RQ.closeModal()">Continue the quest</button></div>`);
      RQ.confetti();
    }
    if(!opts.silent) this.checkBadges(uid);
  },
  badgeDefs(user){
    const kids = RQ.isKidsUser ? RQ.isKidsUser(user) : false;
    return [
      ...(kids? RQ.kidsBadgeDefs() : []),
      {id:'first-lesson',icon:'📘',name:'First Steps',desc:'Complete your first lesson',test:p=>p.stats.lessonsDone>=1},
      {id:'bookworm',icon:'📚',name:'Bookworm',desc:'Complete 5 lessons',test:p=>p.stats.lessonsDone>=5},
      {id:'year-scholar',icon:'🎓',name:'Year Scholar',desc:'Complete every lesson in your year',test:p=>{const u=RQ.Auth.user(); if(!u||u.role!=='student')return false; const ls=RQ.lessonsFor(u.year); return ls.length>0 && ls.every(l=>p.lessons[l.id]&&p.lessons[l.id].done);}},
      {id:'quiz-starter',icon:'🧠',name:'Quiz Starter',desc:'Finish your first quiz',test:p=>p.stats.quizRuns>=1},
      {id:'flawless',icon:'💯',name:'Flawless',desc:'Score 100% on a quiz',test:p=>p.stats.perfect>=1},
      {id:'quiz-regular',icon:'🏆',name:'Quiz Regular',desc:'Complete 5 quizzes',test:p=>p.stats.quizRuns>=5},
      {id:'first-mission',icon:'🤖',name:'Pilot Licence',desc:'Complete your first robot mission',test:p=>p.stats.missionsDone>=1},
      {id:'explorer',icon:'🗺️',name:'Explorer',desc:'Complete 5 robot missions',test:p=>p.stats.missionsDone>=5},
      {id:'boss-slayer',icon:'👑',name:'Boss Slayer',desc:'Defeat your first BOSS challenge',test:p=>RQ.DB.data.missionAttempts.some(a=>a.uid===RQ.Auth.session?.userId&&a.boss&&a.success)},
      {id:'streak-3',icon:'🔥',name:'On Fire',desc:'Learn 3 days in a row',test:p=>p.streak.count>=3},
      {id:'streak-7',icon:'⚡',name:'Unstoppable',desc:'Learn 7 days in a row',test:p=>p.streak.count>=7},
      {id:'code-runner',icon:'💻',name:'Code Runner',desc:'Run code 10 times in Code Lab',test:p=>p.stats.codeRuns>=10},
      {id:'block-builder',icon:'🧩',name:'Block Builder',desc:'Run your first block program',test:p=>p.stats.blockRuns>=1},
      {id:'python-coder',icon:'🐍',name:'Python Coder',desc:'Run your first Python program',test:p=>p.stats.pyRuns>=1},
      {id:'coin-500',icon:'🪙',name:'Coin Collector',desc:'Hold 500 coins at once',test:p=>p.stats.coins>=500},
      {id:'daily-5',icon:'📅',name:'Daily Devotee',desc:'Complete 5 daily challenges',test:p=>p.stats.dailyDone>=5},
      {id:'level-5',icon:'🛠️',name:'Rising Engineer',desc:'Reach Level 5 — Robotics Designer',test:p=>p.stats.xp>=1500},
      {id:'max-level',icon:'👾',name:'Robotics Master',desc:'Reach Level 8 — Robotics Master',test:p=>p.stats.xp>=4000},
      {id:'stars-15',icon:'⭐',name:'Star Collector',desc:'Earn 15 mission stars',test:p=>p.stats.stars>=15},
      {id:'year-champion',icon:'🛡️',name:'Year Champion',desc:'Defeat the BOSS of your year',test:p=>{const u=RQ.Auth.user(); if(!u||u.role!=='student')return false; const boss=RQ.DATA.MISSIONS.find(m=>m.year===u.year&&m.boss); return !!(boss&&p.missions[boss.id]&&p.missions[boss.id].done);}}
    ];
  },
  checkBadges(uid){
    const db=RQ.DB.data; const p=db.progress[uid]; if(!p) return;
    const u=db.users.find(x=>x.id===uid);
    let newly=[];
    for(const b of this.badgeDefs(u)){
      if(p.badges.includes(b.id)) continue;
      let ok=false; try{ ok=b.test(p); }catch(e){}
      if(ok){ p.badges.push(b.id); newly.push(b); }
    }
    if(newly.length){ RQ.DB.save();
      newly.forEach((b,i)=>setTimeout(()=>{ RQ.toast('🏅 Badge earned: '+b.name,'good'); RQ.confetti(); },400+i*900));
    }
  }
};

/* ---------- content lookup helpers ---------- */
RQ.lessonsFor = year => (RQ.DATA.LESSONS[year]||[]);
RQ.lessonsForStudent = u => {
  const db=RQ.DB.data;
  const base=RQ.lessonsFor(u.year).slice();
  const custom=db.customLessons.filter(l=>Number(l.year)===Number(u.year));
  return base.concat(custom.map(RQ.normaliseCustomLesson));
};
RQ.normaliseCustomLesson = l => ({ id:l.id, year:Number(l.year), custom:true, title:l.title,
  objectives:l.objectives||[], learn:[l.body||''], terms:[], understand:[], 
  code:{lang:'txt',title:'Notes',code:l.example||''},
  pred:null, practice:null, kc:[], summary:l.summary||[], xp:l.xp||40, mission:null, unit:'Teacher Lessons' });
RQ.missionsFor = year => RQ.DATA.MISSIONS.filter(m=>m.year===Number(year));
RQ.missionById = id => RQ.DATA.MISSIONS.find(m=>m.id===id) || RQ.DB.data.customMissions.find(m=>m.id===id);
RQ.customMissionsFor = year => RQ.DB.data.customMissions.filter(m=>Number(m.year)===Number(year));
RQ.lessonById = id => { for(const y of RQ.YEARS){ const l=RQ.lessonsFor(y).find(x=>x.id===id); if(l) return l; }
  const c=RQ.DB.data.customLessons.find(x=>x.id===id); return c?RQ.normaliseCustomLesson(c):null; };
RQ.questionsFor = (year,topic) => {
  let qs=RQ.DATA.QUESTIONS.filter(q=>q.year===Number(year));
  const custom=RQ.DB.data.customQuestions.filter(q=>Number(q.year)===Number(year));
  qs=qs.concat(custom);
  if(topic && topic!=='all') qs=qs.filter(q=>q.topic===topic);
  return qs;
};
RQ.quizTopics = year => { const set=new Set();
  RQ.questionsFor(year).forEach(q=>set.add(q.topic));
  return [...set]; };

/* mission unlocking: sequential within a year, boss needs all 5; kids missions are their own ladder */
RQ.missionUnlocked = (u, mission) => {
  const p=RQ.DB.data.progress[u.id];
  if(mission.custom) return true;
  if(mission.kids){
    const list=RQ.DATA.MISSIONS.filter(m=>m.kids);
    const done=m=>!!(p.missions[m.id]&&p.missions[m.id].done);
    const idx=list.findIndex(m=>m.id===mission.id);
    if(idx<=0) return true;
    if(mission.boss) return list.filter(m=>!m.boss).every(done);
    return done(list[idx-1]) || RQ.isAssigned(u,'mission',mission.id);
  }
  const list=RQ.missionsFor(u.year).concat(RQ.customMissionsFor(u.year));
  if(mission.boss) return list.filter(m=>!m.boss).every(m=>p.missions[m.id]&&p.missions[m.id].done);
  const idx=list.findIndex(m=>m.id===mission.id);
  if(idx<=0) return true;
  const prev=list[idx-1];
  return !!(p.missions[prev.id]&&p.missions[prev.id].done) || RQ.isAssigned(u,'mission',mission.id);
};
RQ.lessonUnlocked = (u, lesson) => {
  const p=RQ.DB.data.progress[u.id];
  if(lesson.custom) return true;
  const list=RQ.lessonsForStudent(u); const idx=list.findIndex(l=>l.id===lesson.id);
  if(idx<=0) return true;
  const prev=list[idx-1];
  return !!(p.lessons[prev.id]&&p.lessons[prev.id].done) || RQ.isAssigned(u,'lesson',lesson.id);
};
RQ.isAssigned = (u,kind,refId) => {
  const db=RQ.DB.data;
  const myClasses=db.memberships.filter(m=>m.studentId===u.id).map(m=>m.classId);
  return db.assignments.some(a=>a.kind===kind && a.refId===refId &&
    (a.studentId===u.id || (!a.studentId && myClasses.includes(a.classId))));
};
RQ.myAssignments = u => {
  const db=RQ.DB.data;
  const myClasses=db.memberships.filter(m=>m.studentId===u.id).map(m=>m.classId);
  return db.assignments.filter(a=>a.studentId===u.id || (!a.studentId && myClasses.includes(a.classId)));
};

/* ---------- router ---------- */
RQ.go = (route,param) => { location.hash='#/'+route+(param?('/'+param):''); };
RQ.parseHash = () => {
  const h=(location.hash||'#/welcome').replace(/^#\/?/,'');
  const parts=h.split('/').filter(Boolean);
  return { route:parts[0]||'welcome', param:parts[1]||null };
};
RQ.render = () => {
  const {route,param}=RQ.parseHash();
  const app=document.getElementById('app');
  const u=RQ.Auth.user();
  const pub=['welcome','register','login','parent'];
  if(!u && !pub.includes(route)){ RQ.Auth.restore(); }
  const me=RQ.Auth.user();
  const isPub=!me && pub.includes(route);
  if(!me && !pub.includes(route)){ location.hash='#/login'; return; }
  if(me && pub.includes(route) && route!=='welcome'){ RQ.go(me.role==='teacher'?'t-dash':(RQ.isKidsUser(me)?'k-home':'dash')); return; }
  // track routing: kids students live on the adventure map, academy students on the dashboard
  if(me && me.role==='student'){
    const kidsArea=['k-home','quest','k-robotics','k-studio','studio','k-detective','case','k-arena','k-create','project'];
    if(RQ.isKidsUser(me) && route==='dash'){ RQ.go('k-home'); return; }
    if(!RQ.isKidsUser(me) && kidsArea.includes(route)){ RQ.go('dash'); return; }
  }
  // age-adaptive presentation: bigger targets & text for the youngest learners
  if(me && RQ.isKidsUser(me)){
    const lvl=(RQ.Kids.P(me)&&RQ.Kids.P(me).kids.level)||me.kidsLevel||1;
    document.body.className='kids kids-l'+lvl;
  } else document.body.className=document.body.className.includes('kids')?'':document.body.className;
  const view=RQ.views[route];
  const storeNote = RQ.store.mode==='memory'
    ? '<div class="store-note">⚠️ Sandboxed preview: browser storage is blocked here, so progress will NOT be saved after you leave. Download <b>roboquest.html</b> and open it directly in a browser tab for full persistence.</div>'
    : '';
  const notFound='<div class="empty-state"><div class="ico">🛰️</div>Page not found. <a href="#/dash">Back to base</a></div>';
  if(isPub){
    app.innerHTML='';
    if(!view){ app.innerHTML=notFound; return; }
    try{ view(app,param,me); }catch(e){
      console.error(e);
      app.innerHTML='<div class="empty-state"><div class="ico">⚠️</div>Something went wrong rendering this page.<br><span class="small dim">'+RQ.esc(e.message)+'</span></div>';
    }
    if(storeNote) app.insertAdjacentHTML('afterbegin', storeNote);
  } else {
    app.innerHTML = storeNote + RQ.shellHTML(me,route);
    const host = document.getElementById('view');
    if(!view){ host.innerHTML=notFound; return; }
    try{ view(host,param,me); }catch(e){
      console.error(e);
      host.innerHTML='<div class="empty-state"><div class="ico">⚠️</div>Something went wrong rendering this page.<br><span class="small dim">'+RQ.esc(e.message)+'</span></div>';
    }
  }
  window.scrollTo({top:0});
};
RQ.shellHTML = (u,route) => {
  const isT=u.role==='teacher';
  const isK=!isT && RQ.isKidsUser(u);
  const p=isT?null:RQ.DB.data.progress[u.id];
  const links = isT ? [
    ['t-dash','📊 Overview'],['t-classes','👥 Classes'],['t-assignments','📋 Assignments'],
    ['t-reports','📈 Reports'],['t-insights','🧠 Insights'],['t-content','🛠️ Content Studio'],['t-settings','⚙️ Settings']
  ] : isK ? [
    ['k-home','🗺️ My Adventure'],['k-robotics','🤖 Robotics Lab'],['k-studio','🎮 Game Studio'],
    ['k-detective','🔍 Detective'],['k-arena','🏟️ Arena'],['k-create','🎨 Create'],['achievements','🏅 Badges']
  ] : [
    ['dash','🏠 Dashboard'],['academy','📘 Academy'],['lab','🧪 Code Lab'],['missions','🗺️ Missions'],
    ['quiz','⚔️ Quiz Arena'],['achievements','🏅 Achievements'],
    ['leaderboard','🏆 Leaderboard'],['daily','⚡ Daily']
  ];
  const hl=r=>route===r
    || (r==='k-home'&&['quest','project'].includes(route))
    || (r==='k-robotics'&&route==='mission')
    || (r==='k-studio'&&route==='studio')
    || (r==='k-detective'&&route==='case')
    || (r==='academy'&&route==='lesson')
    || (r==='missions'&&route==='mission');
  const nav=links.map(l=>`<a href="#/${l[0]}" class="${hl(l[0])?'on':''}">${l[1]}</a>`).join('');
  const kidsStars = isK ? RQ.Kids.totalStars(u) : 0;
  const hud = isT ? `<span class="hud-chip lvl">🧑‍🏫 ${RQ.esc(u.name)}</span>`
    : isK ? `<span class="hud-chip xp hide-m">⭐ ${kidsStars} stars</span>
       <span class="hud-chip lvl">${RQ.esc(RQ.KIDS_LEVELS[(RQ.Kids.P(u)&&RQ.Kids.P(u).kids.level)||u.kidsLevel||1].name)}</span>`
    : `<span class="hud-chip xp hide-m">⚡ ${p.stats.xp} XP</span>
       <span class="hud-chip coin hide-m">🪙 ${p.stats.coins}</span>
       <span class="hud-chip lvl">${RQ.Game.levelOf(p.stats.xp).lvl}·${RQ.esc(RQ.Game.levelOf(p.stats.xp).name)}</span>`;
  return `
  <header class="topbar">
    <div class="logo" onclick="RQ.go('${isT?'t-dash':'dash'}')">
      <div class="logo-mark"><svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2"><rect x="5" y="7" width="14" height="10" rx="3"/><circle cx="9.5" cy="12" r="1.6" fill="#fff"/><circle cx="14.5" cy="12" r="1.6" fill="#fff"/><path d="M12 7V3M8 3h8"/></svg></div>
      <div><div class="logo-txt">ROBOQUEST</div><div class="logo-sub">CODE · THINK · BUILD · CONQUER</div></div>
    </div>
    <nav class="nav">${nav}</nav>
    <div class="hud">${hud}
      <button class="avatar-btn" title="${RQ.esc(u.name)}" onclick="RQ.go('${isT?'t-settings':'profile'}')">${RQ.avatarSVG(u.avatar,isT)}</button>
      <button class="burger" onclick="RQ.toggleDrawer(true)">☰</button>
      <button class="btn ghost sm" onclick="RQ.Auth.logout();RQ.render()">Log out</button>
    </div>
  </header>
  <div class="drawer" id="drawer" onclick="if(event.target===this||event.target.classList.contains('drawer-bg'))RQ.toggleDrawer(false)">
    <div class="drawer-bg"></div>
    <div class="drawer-panel">
      <div class="logo-sub" style="margin-bottom:10px">MENU</div>
      ${links.map(l=>`<a href="#/${l[0]}" onclick="RQ.toggleDrawer(false)" class="${route===l[0]?'on':''}">${l[1]}</a>`).join('')}
      <div class="divider"></div>
      <a href="#/${isT?'t-settings':'profile'}" onclick="RQ.toggleDrawer(false)">👤 Profile</a>
      <a href="javascript:RQ.Auth.logout();RQ.render()">🚪 Log out</a>
      <div class="small dim mt">ROBOQUEST · Local Mode v1.0</div>
    </div>
  </div>
  <main class="wrap" id="view"></main>
  <footer class="site">ROBOQUEST — CODE. THINK. BUILD. CONQUER. · Learning platform for ages 7–16</footer>`;
};
RQ.toggleDrawer = open => { const d=document.getElementById('drawer'); if(d) d.classList.toggle('open',open===undefined?!d.classList.contains('open'):open); };
RQ.refreshHUD = () => {
  const u=RQ.Auth.user(); if(!u||u.role!=='student') return;
  const p=RQ.DB.data.progress[u.id]; if(!p) return;
  const xpEl=document.querySelector('.hud-chip.xp'), coinEl=document.querySelector('.hud-chip.coin'), lvlEl=document.querySelector('.hud-chip.lvl');
  if(xpEl) xpEl.textContent='⚡ '+p.stats.xp+' XP';
  if(coinEl) coinEl.textContent='🪙 '+p.stats.coins;
  if(lvlEl) lvlEl.textContent=RQ.Game.levelOf(p.stats.xp).lvl+'·'+RQ.Game.levelOf(p.stats.xp).name;
};

/* ---------- UI kit ---------- */
RQ.toast = (msg,kind) => {
  let host=document.getElementById('toasts');
  if(!host){ host=document.createElement('div'); host.id='toasts'; document.body.appendChild(host); }
  const t=document.createElement('div'); t.className='toast '+(kind||''); t.textContent=msg;
  host.appendChild(t); setTimeout(()=>{ t.style.opacity='0'; t.style.transition='opacity .4s'; setTimeout(()=>t.remove(),400); },3400);
};
RQ.modal = html => {
  RQ.closeModal();
  const bg=document.createElement('div'); bg.className='modal-bg'; bg.id='rq-modal';
  bg.innerHTML=`<div class="modal" onclick="event.stopPropagation()">${html}
    <div class="center mt"><button class="btn ghost sm" onclick="RQ.closeModal()">Close</button></div></div>`;
  bg.addEventListener('click',e=>{ if(e.target===bg) RQ.closeModal(); });
  document.body.appendChild(bg);
};
RQ.closeModal = () => { const m=document.getElementById('rq-modal'); if(m) m.remove(); };
RQ.confirm = (msg, onYes) => {
  RQ.modal(`<h3>⚠️ Please confirm</h3><p class="muted mt-s">${RQ.esc(msg)}</p>
    <div class="row end mt"><button class="btn ghost sm" onclick="RQ.closeModal()">Cancel</button>
    <button class="btn danger sm" id="cf-yes">Confirm</button></div>`);
  document.getElementById('cf-yes').onclick=()=>{ RQ.closeModal(); onYes(); };
};
RQ.confetti = () => {
  const c=document.createElement('canvas'); c.className='confetti'; c.width=innerWidth; c.height=innerHeight;
  document.body.appendChild(c); const ctx=c.getContext('2d');
  const cols=['#26d9f2','#4f7cff','#a78bfa','#34d399','#fbbf24','#f472b6'];
  const ps=Array.from({length:110},()=>({x:Math.random()*c.width,y:-20-Math.random()*c.height*.5,
    v:2+Math.random()*3.4, w:5+Math.random()*6, col:cols[Math.floor(Math.random()*6)], spin:Math.random()*6.28}));
  let frames=0;
  (function tick(){
    ctx.clearRect(0,0,c.width,c.height); frames++;
    ps.forEach(p=>{ p.y+=p.v; p.spin+=.1; ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(p.spin);
      ctx.fillStyle=p.col; ctx.fillRect(-p.w/2,-p.w/4,p.w,p.w/2); ctx.restore(); });
    if(frames<150) requestAnimationFrame(tick); else c.remove();
  })();
};

/* ---------- avatar ---------- */
