    starter:[], goalText:'FINAL BOSS: two crystals on a winding route. Combine your powers: a function, dials, or a repeat — any working program wins. Elegance earns stars!',
    solution:[DEF('go',[MV()]),CALL('go',4),TR(),CALL('go',2),TR(),CALL('go',2),TL(),CALL('go',2),TR(),CALL('go',2)], maxBlocks:14,
