/* ---------- register (wizard) ---------- */
RQ.views.register = function(host){
  const st={step:1, name:'', username:'', password:'', year:8, track:'academy', kidsLevel:1, color:RQ.AVATAR_COLORS[0], classCode:''};
  const colors=RQ.AVATAR_COLORS;
  function render(){
    let body='';
    if(st.step===1){
      body=`<h2 class="center">Create your student account</h2>
      <div class="err-msg" id="reg-err" style="display:none"></div>
      <div class="field"><label>Display name</label><input id="r-name" maxlength="24" placeholder="e.g. Alex Chen" value="${RQ.esc(st.name)}"></div>
      <div class="field"><label>Username</label><input id="r-user" maxlength="16" placeholder="lowercase letters & numbers" value="${RQ.esc(st.username)}"></div>
      <div class="grid g2"><div class="field"><label>Password (6+)</label><div class="pw-wrap"><input id="r-pass" type="password" autocomplete="new-password"><button type="button" class="pw-eye" onclick="RQ.pwEye('r-pass',this)">👁 Show</button></div></div>
      <div class="field"><label>Confirm password</label><div class="pw-wrap"><input id="r-pass2" type="password" autocomplete="new-password"><button type="button" class="pw-eye" onclick="RQ.pwEye('r-pass2',this)">👁 Show</button></div></div></div>
      <button class="btn primary block" id="r-next1">Choose your age group →</button>`;
    } else if(st.step===2){
      const ageOpts=[
        {track:'kids', lvl:1, ages:'7–8',  name:'Little Coders',      emoji:'🐣', color:'#34d399', note:'Playful worlds, big buttons, read-along stories'},
        {track:'kids', lvl:2, ages:'9–10', name:'Junior Programmers', emoji:'🚀', color:'#26d9f2', note:'Variables, functions and your first games'},
        {track:'kids', lvl:3, ages:'11–12',name:'Young Developers',   emoji:'🛠️', color:'#a78bfa', note:'Algorithms, data, debugging and real code'},
        {track:'academy', lvl:0, ages:'12+', name:'Robotics Academy (Years 8–11)', emoji:'🤖', color:'#4f7cff', note:'Python engineering, robotics missions & quizzes'}
      ];
      body=`<h2 class="center">How old are you?</h2>
      <p class="muted center small">We'll pick the right learning adventure for your age. You can always move up later — and a teacher can adjust it.</p>
      <div class="grid g2 mt-s">
        ${ageOpts.map(o=>`<div class="year-pill ${st.track===o.track&&(o.track==='academy'||st.kidsLevel===o.lvl)?'sel':''}" data-track="${o.track}" data-lvl="${o.lvl}">
          <b style="color:${o.color}">${o.emoji} AGE ${o.ages}</b><small>${o.name}</small>
          <div class="small dim mt-s">${o.note}</div></div>`).join('')}
      </div>
      ${st.track==='academy'?`<div class="field mt"><label>Which school year are you in?</label>
        <div class="grid g2">${RQ.YEARS.map(y=>{const m=RQ.YEAR_META[y];return `
        <div class="year-pill yr-sm ${st.year===y?'sel':''}" data-year="${y}">
          <b style="color:${m.color}">YEAR ${y} — ${m.name}</b><small>${m.tag}</small></div>`;}).join('')}</div></div>`:''}
      <div class="field mt"><label>Pick your robot avatar</label>
        <div class="avatar-grid">${colors.map(c=>`<div class="avatar-opt ${st.color===c?'sel':''}" data-color="${c}">${RQ.avatarSVG({color:c})}</div>`).join('')}</div>
      </div>
      <div class="row"><button class="btn ghost" id="r-back2">← Back</button><button class="btn primary" style="flex:1" id="r-next2">Almost done →</button></div>`;
    } else {
      body=`<h2 class="center">Join your class (optional)</h2>
      <p class="muted center small">Enter the join code your teacher gave you — or skip and join later from your profile.</p>
      <div class="field"><input id="r-code" maxlength="8" placeholder="e.g. RQ7K2P" style="text-transform:uppercase;text-align:center;font-size:1.3rem;letter-spacing:4px" value="${RQ.esc(st.classCode)}"></div>
      <div class="err-msg" id="reg-err2" style="display:none"></div>
      <div class="row"><button class="btn ghost" id="r-back3">← Back</button><button class="btn primary" style="flex:1" id="r-finish">🏁 Create account & start quest</button></div>
      <p class="center dim small mt">By creating an account you agree this is an educational platform. Progress is stored on this device.</p>`;
    }
    host.innerHTML=`<div class="wrap" style="max-width:640px">
      <div class="center mb"><div class="logo" style="justify-content:center;display:flex" onclick="RQ.go('welcome')">
        <div class="logo-mark"><svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2"><rect x="5" y="7" width="14" height="10" rx="3"/><circle cx="9.5" cy="12" r="1.6" fill="#fff"/><circle cx="14.5" cy="12" r="1.6" fill="#fff"/><path d="M12 7V3M8 3h8"/></svg></div>
        <div class="logo-txt">ROBOQUEST</div></div></div>
      <div class="row" style="justify-content:center;margin-bottom:18px">
        ${[1,2,3].map(i=>`<span class="stepdot ${st.step===i?'on':(st.step>i?'done':'')}"><span class="n">${st.step>i?'✓':i}</span>${['Account','Age & avatar','Class'][i-1]}</span>${i<3?'<span class="step-link"></span>':''}`).join('')}
      </div>
      <div class="card">${body}</div>
      <p class="center small dim mt">Already have an account? <a href="#/login">Log in</a></p>
    </div>`;
    // bindings
    const err=(id,msg)=>{ const e=host.querySelector('#'+id); if(e){e.textContent=msg;e.style.display='block';} };
    if(st.step===1){
      host.querySelector('#r-next1').onclick=()=>{
        st.name=host.querySelector('#r-name').value.trim();
        st.username=host.querySelector('#r-user').value.trim().toLowerCase();
        const p1=host.querySelector('#r-pass').value, p2=host.querySelector('#r-pass2').value;
        host.querySelector('#reg-err').style.display='none';
        if(st.name.length<2) return err('reg-err','Please enter your display name.');
        if(!/^[a-z0-9_]{3,16}$/.test(st.username)) return err('reg-err','Username must be 3-16 letters/numbers/underscores (no spaces).');
        if(p1.length<6) return err('reg-err','Password must be at least 6 characters.');
        if(p1!==p2) return err('reg-err','Passwords do not match.');
        if(RQ.DB.data.users.some(u=>u.username===st.username)) return err('reg-err','That username is already taken.');
        st.password=p1; st.step=2; render();
      };
    } else if(st.step===2){
      host.querySelectorAll('.year-pill:not(.yr-sm)').forEach(el=>el.onclick=()=>{
        st.track=el.dataset.track;
        if(st.track==='kids') st.kidsLevel=Number(el.dataset.lvl)||1;
        render();
      });
      host.querySelectorAll('.year-pill.yr-sm').forEach(el=>el.onclick=()=>{ st.year=Number(el.dataset.year); render(); });
      host.querySelectorAll('.avatar-opt').forEach(el=>el.onclick=()=>{ st.color=el.dataset.color; render(); });
      host.querySelector('#r-back2').onclick=()=>{ st.step=1; render(); };
      host.querySelector('#r-next2').onclick=()=>{ st.step=3; render(); };
    } else {
      host.querySelector('#r-back3').onclick=()=>{ st.step=2; render(); };
      host.querySelector('#r-finish').onclick=async()=>{
        st.classCode=host.querySelector('#r-code').value.trim();
        host.querySelector('#reg-err2').style.display='none';
        try{
          const res=await RQ.Auth.registerStudent({name:st.name, username:st.username, password:st.password,
            year:st.year, track:st.track, kidsLevel:st.kidsLevel, avatar:{color:st.color}, classCode:st.classCode});
          RQ.Auth.setSession({userId:res.user.id, role:'student', at:Date.now()});
          RQ.Game.award(res.user.id, 20, 50, 'Welcome to ROBOQUEST!', {silent:true});
          RQ.confetti();
          RQ.toast(res.joined? ('Joined class '+res.joined+'!') : 'Account created — welcome!');
          RQ.go(st.track==='kids'?'k-home':'dash');
        }catch(e){ err('reg-err2', e.message); }
      };
    }
  }
  render();
};

/* ---------- login ---------- */
RQ.views.login = function(host){
  let mode='student';
  function render(){
    host.innerHTML=`<div class="wrap" style="max-width:480px">
      <div class="center mb"><div class="logo" style="justify-content:center;display:flex" onclick="RQ.go('welcome')">
        <div class="logo-mark"><svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2"><rect x="5" y="7" width="14" height="10" rx="3"/><circle cx="9.5" cy="12" r="1.6" fill="#fff"/><circle cx="14.5" cy="12" r="1.6" fill="#fff"/><path d="M12 7V3M8 3h8"/></svg></div>
        <div class="logo-txt">ROBOQUEST</div></div>
        <div class="tag" style="font-size:.7rem;letter-spacing:3px;margin-top:8px">CODE · THINK · BUILD · CONQUER</div></div>
      <div class="tabs" style="justify-content:center">
        <div class="tab ${mode==='student'?'on':''}" id="t-student">🎓 Student</div>
        <div class="tab ${mode==='teacher'?'on':''}" id="t-teacher">🧑‍🏫 Teacher</div>
      </div>
      <div class="card">
        <div class="err-msg" id="l-err" style="display:none"></div>
        <div class="field"><label>Username</label><input id="l-user" autocomplete="username"></div>
        <div class="field"><label>Password</label><div class="pw-wrap"><input id="l-pass" type="password" autocomplete="current-password"><button type="button" class="pw-eye" onclick="RQ.pwEye('l-pass',this)">👁 Show</button></div></div>
        <button class="btn primary block" id="l-go">Enter ${mode==='student'?'the quest':'the staff room'} →</button>
        ${mode==='teacher'?`<p class="small dim mt">New teacher? Register with your school invite code: <a href="javascript:RQ.teacherRegister()">Create teacher account</a></p>`
          :`<p class="small dim mt center">New student? <a href="#/register">Create your account</a></p>`}
      </div>
      <div class="card mt center">
        <p class="dim small">Demo accounts — student: <b class="mono">demo_novabyte</b> (any password? no — use the demo button) · teacher: <b class="mono">teacher</b> / <b class="mono">robotics2026</b></p>
        <button class="btn ghost sm mt-s" id="l-demo">Log in as demo teacher</button>
        <p class="small dim mt-s">👨‍👩‍👧 Parent? <a href="#/parent">See your child's progress</a> (code on their profile page)</p>
      </div>
    </div>`;
    host.querySelector('#t-student').onclick=()=>{ mode='student'; render(); };
    host.querySelector('#t-teacher').onclick=()=>{ mode='teacher'; render(); };
    host.querySelector('#l-demo').onclick=async()=>{
      host.querySelector('#l-user').value='teacher'; host.querySelector('#l-pass').value='robotics2026';
      try{ const u=await RQ.Auth.login('teacher','robotics2026'); RQ.toast('Welcome back, '+u.name); RQ.go('t-dash'); }
      catch(e){ const el=host.querySelector('#l-err'); el.textContent=e.message; el.style.display='block'; }
    };
    const go=async()=>{
      const u=host.querySelector('#l-user').value.trim();
      const p=host.querySelector('#l-pass').value;
      host.querySelector('#l-err').style.display='none';
      try{
        const user=await RQ.Auth.login(u,p);
        if(user.role==='teacher'){ RQ.toast('Welcome back, '+user.name); RQ.go('t-dash'); }
        else { const cls=RQ.Auth.studentClass(user.id); RQ.toast('Welcome back, '+user.name+(cls? ' ('+cls.name+')':'')); RQ.go('dash'); }
      }catch(e){ const el=host.querySelector('#l-err'); el.textContent=e.message; el.style.display='block'; }
    };
    host.querySelector('#l-go').onclick=go;
    host.querySelector('#l-pass').addEventListener('keydown',e=>{ if(e.key==='Enter') go(); });
  }
  render();
};
RQ.teacherRegister = function(){
  RQ.modal(`<h3>Create teacher account</h3>
  <p class="small dim">Requires the school invite code (ask your admin). Demo code: ROBOSTAFF</p>
  <div class="field"><label>Full name</label><input id="tr-name"></div>
  <div class="field"><label>Username</label><input id="tr-user"></div>
  <div class="field"><label>Password (8+)</label><div class="pw-wrap"><input id="tr-pass" type="password" autocomplete="new-password"><button type="button" class="pw-eye" onclick="RQ.pwEye('tr-pass',this)">👁 Show</button></div></div>
  <div class="field"><label>Invite code</label><input id="tr-invite"></div>
  <div class="err-msg" id="tr-err" style="display:none"></div>
  <button class="btn primary block" id="tr-go">Create account</button>`);
  document.getElementById('tr-go').onclick=async()=>{
    try{
      const u=await RQ.Auth.registerTeacher({
        name:document.getElementById('tr-name').value,
        username:document.getElementById('tr-user').value,
        password:document.getElementById('tr-pass').value,
        invite:document.getElementById('tr-invite').value});
      RQ.closeModal(); RQ.Auth.setSession({userId:u.id, role:'teacher', at:Date.now()});
      RQ.toast('Teacher account created'); RQ.go('t-dash');
    }catch(e){ const el=document.getElementById('tr-err'); el.textContent=e.message; el.style.display='block'; }
  };
};

/* ---------- student dashboard ---------- */
RQ.continueTarget = function(u){
  const p=RQ.DB.data.progress[u.id];
  // assigned work first
  const asg=RQ.myAssignments(u);
  for(const a of asg){
    if(a.kind==='lesson'){ const l=RQ.lessonById(a.refId); if(l && !(p.lessons[l.id]&&p.lessons[l.id].done)) return {type:'lesson', id:l.id, label:'Assigned lesson: '+l.title}; }
    if(a.kind==='mission'){ const m=RQ.missionById(a.refId); if(m && !(p.missions[m.id]&&p.missions[m.id].done)) return {type:'mission', id:m.id, label:'Assigned mission: '+m.title}; }
    if(a.kind==='quiz' && !(p.quizzes[a.refId]&&p.quizzes[a.refId].best)) return {type:'quiz', id:a.refId, label:'Assigned quiz: '+a.title};
  }
  const lessons=RQ.lessonsForStudent(u);
  for(const l of lessons){ if(!(p.lessons[l.id]&&p.lessons[l.id].done) && RQ.lessonUnlocked(u,l)) return {type:'lesson', id:l.id, label:'Next lesson: '+l.title}; }
  const missions=RQ.missionsFor(u.year).concat(RQ.customMissionsFor(u.year));
  for(const m of missions){ if(!(p.missions[m.id]&&p.missions[m.id].done) && RQ.missionUnlocked(u,m)) return {type:'mission', id:m.id, label:'Next mission: '+m.title}; }
  return {type:'daily', id:null, label:'Today\u2019s daily challenge'};
};
RQ.views.dash = function(host,param,me){
  const db=RQ.DB.data, p=db.progress[me.id], lvl=RQ.Game.levelOf(p.stats.xp), nxt=RQ.Game.nextLevel(p.stats.xp);
  const cls=RQ.Auth.studentClass(me.id);
  const lessons=RQ.lessonsForStudent(me.id);
  const lessonsDone=lessons.filter(l=>p.lessons[l.id]&&p.lessons[l.id].done).length;
  const missions=RQ.missionsFor(me.year).concat(RQ.customMissionsFor(me.id?me.id:me.id)); // includes custom
  const missionsDone=RQ.missionsFor(me.year).filter(m=>p.missions[m.id]&&p.missions[m.id].done).length;
  const pct=nxt? Math.min(100,Math.round(((p.stats.xp-lvl.xp)/(nxt.xp-lvl.xp))*100)) : 100;
  const target=RQ.continueTarget(me);
  const asg=RQ.myAssignments(me);
  const today=RQ.todayKey();
  const dailyDone=p.daily&&p.daily.date===today;
  const badgesEarned=p.badges.length;
  // leaderboard position
  const others=db.users.filter(u=>u.role==='student').map(u=>({u, xp:(db.progress[u.id]||{stats:{xp:0}}).stats.xp}))
    .sort((a,b)=>b.xp-a.xp);
  const rank=others.findIndex(x=>x.u.id===me.id)+1;
  const navCards=[
    ['academy','📘','Coding Academy','Structured lessons for Year '+me.year],
    ['lab','🧪','Code Lab','Blocks, pseudocode & Python'],
    ['lab','🧪','Code Lab','Blocks, Scratch, pseudocode & Python'],
    ['missions','🗺️','Mission Challenges',missionsDone+'/'+RQ.missionsFor(me.year).length+' complete'],
    ['quiz','⚔️','Quiz Arena','Earn XP with quick-fire questions'],
    ['achievements','🏅','Achievement Centre',badgesEarned+' badges earned'],
    ['leaderboard','🏆','Leaderboard','School rankings'],
    ['daily','⚡','Daily Challenge',dailyDone?'✅ Done today!':'New challenge every day']
  ];
  host.innerHTML=`
  <div class="page-head"><div><div class="page-title">Command <span class="accent">Centre</span></div>
  <div class="page-sub">Your mission control for Year ${me.year} — ${RQ.YEAR_META[me.year].name}${cls? ' · Class: '+RQ.esc(cls.name):''}</div></div></div>
  <div class="dash-hero">
    <div style="width:84px;height:84px" class="avatar-lg">${RQ.avatarSVG(me.avatar)}</div>
    <div class="who">
      <h2>${RQ.esc(me.name)} <span class="chip pu">Year ${me.year}</span> ${me.demo?'<span class="chip">demo</span>':''}</h2>
      <div class="level-track">
        <div class="row between small"><span class="muted">Level ${lvl.lvl} — <b style="color:var(--pu)">${lvl.name}</b></span>
        <span class="dim">${nxt? (p.stats.xp+' / '+nxt.xp+' XP') : 'MAX LEVEL'}</span></div>
        <div class="bar mt-s"><div class="fill" style="width:${pct}%"></div></div>
      </div>
      <div class="row mt-s">
        <span class="chip cy">⚡ ${p.stats.xp} XP</span><span class="chip am">🪙 ${p.stats.coins} coins</span>
        <span class="chip rd">🔥 ${p.streak.count}-day streak</span><span class="chip gr">🏆 Rank #${rank||'—'}</span>
      </div>
    </div>
    <div style="text-align:center">
      <button class="btn primary big" onclick="RQ.continueGo()">▶ CONTINUE LEARNING</button>
      <div class="small dim mt-s" style="max-width:220px">${RQ.esc(target.label)}</div>
    </div>
  </div>
  <div class="grid g4 mt">
    <div class="card center"><div class="stat-num glow-cy">${lessonsDone}/${lessons.length}</div><div class="stat-lbl">Lessons complete</div></div>
    <div class="card center"><div class="stat-num" style="color:var(--gr)">${missionsDone}/6</div><div class="stat-lbl">Missions complete</div></div>
    <div class="card center"><div class="stat-num" style="color:var(--am)">${p.stats.quizRuns}</div><div class="stat-lbl">Quizzes taken</div></div>
    <div class="card center"><div class="stat-num" style="color:var(--pk)">${p.stats.stars}</div><div class="stat-lbl">Mission stars</div></div>
  </div>
  ${asg.length? `<div class="card mt"><h3>📋 Assigned by your teacher</h3>
    ${asg.map(a=>`<div class="row between mt-s" style="border-bottom:1px dashed var(--line);padding:8px 0">
      <span><span class="chip">${a.kind}</span> ${RQ.esc(a.title)}</span>
      <button class="btn sm primary" onclick="RQ.go('${a.kind==='lesson'?'lesson':a.kind==='mission'?'mission':'quiz'}','${a.refId}')">Open →</button>
    </div>`).join('')}</div>`:''}
  <div class="grid auto nav-cards mt">
    ${navCards.map(n=>`<div class="card hover" onclick="RQ.go('${n[0]}')">
      <div class="icon-tile">${n[1]}</div><div><h3>${n[2]}</h3><p>${n[3]}</p></div></div>`).join('')}
  </div>`;
};
RQ.continueGo = function(){
  const me=RQ.Auth.user(); if(!me) return;
  const t=RQ.continueTarget(me);
  if(t.type==='lesson') RQ.go('lesson',t.id);
  else if(t.type==='mission') RQ.go('mission',t.id);
  else if(t.type==='quiz') RQ.go('quiz',t.id);
  else RQ.go('daily');
};

/* ---------- academy (lesson list) ---------- */
RQ.views.academy = function(host,param,me){
  const p=RQ.DB.data.progress[me.id];
  const lessons=RQ.lessonsForStudent(me.id);
  const units={};
  lessons.forEach(l=>{ (units[l.unit]=units[l.unit]||[]).push(l); });
  const done=lessons.filter(l=>p.lessons[l.id]&&p.lessons[l.id].done).length;
  host.innerHTML=`
  <div class="page-head"><div><div class="page-title">Coding <span class="accent">Academy</span></div>
  <div class="page-sub">Year ${me.year} pathway — ${done}/${lessons.length} lessons complete. Lessons unlock in order; finish each one to advance.</div></div>
  <div style="min-width:220px"><div class="row between small"><span class="dim">Pathway progress</span><span class="muted">${Math.round(done/lessons.length*100)}%</span></div>
  <div class="bar mt-s"><div class="fill" style="width:${Math.round(done/lessons.length*100)}%"></div></div></div></div>
  ${Object.keys(units).map(unit=>`
    <h3 class="mt" style="letter-spacing:1px;color:var(--mut)">▸ ${RQ.esc(unit)}</h3>
    <div class="grid auto mt-s">
      ${units[unit].map((l,idx)=>{
        const pr=p.lessons[l.id]||{};
        const unlocked=RQ.lessonUnlocked(me,l);
        const state=pr.done?'done':(unlocked?'next':'locked');
        return `<div class="card hover" style="${state==='locked'?'opacity:.55':''}" onclick="${unlocked?`RQ.go('lesson','${l.id}')`:''}">
          <div class="row between"><div class="icon-tile" style="${state==='done'?'background:linear-gradient(135deg,#0ea968,#34d399)':''}">${pr.done?'✓':state==='locked'?'🔒':l.custom?'🧑‍🏫':'📘'}</div>
          <span class="chip ${pr.done?'gr':''}">${pr.done?'Complete':(l.xp+' XP')}</span></div>
          <h3 class="mt-s">${RQ.esc(l.title)}</h3>
          <p>${l.custom? 'Teacher lesson · ' : ''}${l.objectives? RQ.esc(l.objectives[0]||'') : ''}</p>
          <div class="small dim mt-s">Lesson ${idx+1} ${pr.step? ' · step '+Math.min(pr.step,7)+'/7':''}</div>
        </div>`;}).join('')}
    </div>`).join('')}`;
};

/* ---------- lesson player (7 steps) ---------- */
RQ.views.lesson = function(host, id, me){
  const l=RQ.lessonById(id);
  if(!l || l.year!==me.year && !l.custom){ host.innerHTML='<div class="empty-state">Lesson not found for your year. <a href="#/academy">Back to Academy</a></div>'; return; }
  const p=RQ.DB.data.progress[me.id];
  const pr=p.lessons[l.id]=p.lessons[l.id]||{step:1};
  const STEPS=['Learn','Understand','See it work','Predict','Practise','Mission','Knowledge test'];
  if(pr.step>7) pr.step=7;
  let state={step:pr.step||1, predictDone:!!pr.predict, practiceDone:!!pr.practice, kcAnswers:{}, kcTried:pr.kcTried||{}};
  function save(){ RQ.DB.save(); }
  function awardOnce(key, xp, coins, reason){
    if(pr[key]) return; pr[key]=true; save();
    RQ.Game.award(me.id, xp, coins||0, reason);
  }
  function render(){
    const s=state.step;
    const dots=STEPS.map((t,i)=>`<span class="stepdot ${s===i+1?'on':(s>i+1||isDone(i+1))?'done':''}" style="cursor:pointer" onclick="RQ._ls(${i+1})"><span class="n">${s>i+1||isDone(i+1)?'✓':i+1}</span>${t}</span>${i<6?'<span class="step-link"></span>':''}`).join('');
    host.innerHTML=`<div class="page-head"><div>
      <div class="page-title">${RQ.esc(l.title)}</div>
      <div class="page-sub">${l.custom?'Teacher lesson':'Year '+l.year+' · '+RQ.esc(l.unit)} · ${l.xp} XP on completion</div></div>
      <button class="btn ghost sm" onclick="RQ.go('academy')">← Academy</button></div>
    <div class="stepper">${dots}</div>
    <div class="card lesson-body" id="lstep"></div>
    <div class="row between mt">
      <button class="btn ghost" id="l-prev" ${s===1?'disabled':''}>← Back</button>
      ${s===7? `<button class="btn primary big" id="l-finish">${allKcCorrect()?'🏁 Complete lesson':'Answer all questions to finish'}</button>`
        : `<button class="btn primary" id="l-next">Next: ${STEPS[s]} →</button>`}
    </div>`;
    renderStep(s);
    host.querySelector('#l-prev').onclick=()=>{ if(state.step>1){ state.step--; save(); render(); } };
    const nb=host.querySelector('#l-next');
    if(nb) nb.onclick=()=>{ if(state.step<7){ state.step=Math.max(state.step+1,(pr.step||1)+0); pr.step=Math.max(pr.step||1,state.step); save(); render(); } };
    const fb=host.querySelector('#l-finish');
    if(fb) fb.onclick=()=>{
      if(!allKcCorrect()) { RQ.toast('Answer every knowledge check correctly first','bad'); return; }
      pr.done=true; pr.step=7; pr.ts=Date.now(); save();
      if(!pr.awarded){ pr.awarded=true; save(); RQ.Game.award(me.id, l.xp, Math.round(l.xp/3), 'Lesson complete: '+l.title); }
      RQ.confetti();
      RQ.modal(`<div class="reward-pop center"><div class="big-ico">🎓</div><h2>Lesson complete!</h2>
        <p class="muted">${RQ.esc(l.title)} — +${l.xp} XP earned.</p>
        ${l.mission? '<p class="small dim">Now apply it: the linked robot mission awaits.</p>':''}
        <div class="row mt" style="justify-content:center">
          ${l.mission? `<button class="btn primary" onclick="RQ.closeModal();RQ.go('mission','${l.mission}')">🤖 Do the linked mission</button>`:''}
          <button class="btn ghost" onclick="RQ.closeModal();RQ.go('academy')">Back to Academy</button>
        </div></div>`);
    };
  }
  RQ._ls=(n)=>{ state.step=n; pr.step=Math.max(pr.step||1,n); save(); render(); };
  function isDone(n){ // step considered done if its interaction succeeded
    if(n===4) return state.predictDone;
    if(n===5) return state.practiceDone;
    if(n===7) return allKcCorrect();
    return state.step>n;
  }
  function allKcCorrect(){ return l.kc.length>0 && l.kc.every((q,i)=>state.kcAnswers[i]===q.a); }
  function renderStep(s){
    const el=host.querySelector('#lstep');
    if(s===1){
      el.innerHTML=`<h2>🎓 Step 1 — Learn</h2>
        <div class="card mb" style="background:rgba(38,217,242,.06)"><b class="small" style="color:var(--cy);letter-spacing:1px">LEARNING OBJECTIVES</b>
        <ul class="obj-list">${l.objectives.map(o=>'<li>'+RQ.esc(o)+'</li>').join('')}</ul></div>
        ${l.learn.map(p=>'<p>'+RQ.esc(p).replace(/\u2019/g,'’')+'</p>').join('')}
        ${l.terms.length? `<h3 class="mt">Key terminology</h3><div class="term-grid">${l.terms.map(t=>`<div class="term-card"><b>${RQ.esc(t[0])}</b><span>${RQ.esc(t[1])}</span></div>`).join('')}</div>`:''}`;
    } else if(s===2){
      el.innerHTML=`<h2>💡 Step 2 — Understand</h2>
        ${l.understand.map(u=>`<div class="card mb-s" style="background:var(--panel2)"><h3>${RQ.esc(u[0])}</h3><p>${RQ.esc(u[1])}</p></div>`).join('')}
        <p class="dim small">Real-world context: these are the situations where today\u2019s concept earns its keep.</p>`;
    } else if(s===3){
      el.innerHTML=`<h2>👀 Step 3 — See it work</h2>
        <div class="codeblock mb"><div class="hd"><span>${RQ.esc(l.code.title||'Example')}</span><span>${l.code.lang==='python'?'python':l.code.lang==='ps'?'pseudocode':'robot code'}</span></div>
        <pre>${RQ.highlight(l.code.code, l.code.lang==='python'?'python':'dsl')}</pre></div>
        <ul class="sum-list">${(l.code.notes||[]).map(n=>'<li>'+RQ.esc(n)+'</li>').join('')}</ul>`;
    } else if(s===4){
      const prd=l.pred;
      el.innerHTML=`<h2>🔮 Step 4 — Predict</h2>
        <p class="muted">Before you run anything — what will happen? ${prd.code?`<div class="codeblock mt-s mb-s"><pre>${RQ.highlight(prd.code, l.code.lang==='python'?'python':'dsl')}</pre></div>`:''}</p>
        <div class="quiz-q">${RQ.esc(prd.q)}</div>
        <div id="pred-opts">${prd.o.map((o,i)=>`<button class="opt" data-i="${i}"><span class="key">${'ABCD'[i]}</span>${RQ.esc(o)}</button>`).join('')}</div>
        <div id="pred-fb"></div>`;
      el.querySelectorAll('#pred-opts .opt').forEach(b=>b.onclick=()=>{
        const i=Number(b.dataset.i);
        el.querySelectorAll('#pred-opts .opt').forEach(x=>{x.disabled=true; if(x.dataset.i==String(prd.a)) x.classList.add('correct'); else if(x.dataset.i==String(i)) x.classList.add('wrong');});
        const ok=i===prd.a;
        state.predictDone=true;
        el.querySelector('#pred-fb').innerHTML=`<div class="explain-box"><b>${ok?'✅ Correct!':'❌ Not quite.'}</b> ${RQ.esc(prd.e)}</div>`;
        if(ok) awardOnce('predict', 10, 0, 'Sharp prediction!');
        else { pr.predictWrong=true; save(); }
        pr.predict=true; save(); refreshDots();
      });
    } else if(s===5){
      const p5=l.prac;
      if(!p5){ el.innerHTML='<h2>🛠️ Step 5 — Practise</h2><p class="muted">This lesson links directly to a robot mission — the practice happens there. Continue to the knowledge test.</p>'; state.practiceDone=true; return; }
      let inner='';
      if(p5.type==='mc'){
        inner=`<div class="quiz-q">${RQ.esc(p5.q)}</div><div id="prac-opts">${p5.o.map((o,i)=>`<button class="opt" data-i="${i}"><span class="key">${'ABCD'[i]}</span>${RQ.esc(o)}</button>`).join('')}</div><div id="prac-fb"></div>`;
      } else if(p5.type==='out'){
        inner=`<div class="quiz-q">${RQ.esc(p5.q)}</div>
        ${p5.code?`<div class="codeblock mb-s"><pre>${RQ.highlight(p5.code,'python')}</pre></div>`:''}
        <div class="field"><label>Your prediction of the output</label><input id="prac-in" class="mono" placeholder="type the exact output"></div>
        <button class="btn primary" id="prac-check">Check answer</button><div id="prac-fb"></div>`;
      } else if(p5.type==='py'){
        inner=`<div class="quiz-q">${RQ.esc(p5.q)}</div>
        <div class="editor-wrap mb-s"><textarea id="prac-code" spellcheck="false">${RQ.esc(p5.starter||'')}</textarea></div>
        <button class="btn primary" id="prac-run">▶ Run my code</button>
        <div class="terminal mt-s" id="prac-term">// output appears here</div><div id="prac-fb"></div>`;
      } else if(p5.type==='ps'){
        inner=`<div class="quiz-q">${RQ.esc(p5.q)}</div>
        <div class="field"><label>Your pseudocode</label><textarea id="prac-code" spellcheck="false">${RQ.esc(p5.starter||'')}</textarea></div>
        <button class="btn primary" id="prac-check">Check pseudocode</button><div id="prac-fb"></div>`;
      }
      el.innerHTML=`<h2>🛠️ Step 5 — Practise</h2>${inner}`;
      const fb=el.querySelector('#prac-fb');
      const done=(ok,msg)=>{
        state.practiceDone=ok||state.practiceDone;
        fb.innerHTML=`<div class="explain-box"><b>${ok?'✅ Success!':'❌ Try again.'}</b> ${msg}</div>`;
        if(ok) awardOnce('practice', 15, 0, 'Practice complete!');
        pr.practice=true; save(); refreshDots();
      };
      if(p5.type==='mc'){
        el.querySelectorAll('#prac-opts .opt').forEach(b=>b.onclick=()=>{
          const i=Number(b.dataset.i), ok=i===p5.a;
          el.querySelectorAll('#prac-opts .opt').forEach(x=>{x.disabled=true; if(Number(x.dataset.i)===p5.a) x.classList.add('correct'); else if(Number(x.dataset.i)===i) x.classList.add('wrong');});
          done(ok, RQ.esc(p5.e||''));
        });
      } else if(p5.type==='out'){
        el.querySelector('#prac-check').onclick=()=>{
          const v=el.querySelector('#prac-in').value.trim();
          const ok=v===p5.a || v.replace(/\s+/g,' ')===p5.a.replace(/\s+/g,' ');
          done(ok, ok? 'Exactly right — the output is '+p5.a+'.':'Expected: '+p5.a);
        };
      } else if(p5.type==='py'){
        el.querySelector('#prac-run').onclick=()=>{
          const src=el.querySelector('#prac-code').value;
          const term=el.querySelector('#prac-term');
          let out=[], err=null;
          try{ out=runLessonPy(src); }catch(e){ err=e.message; }
          term.innerHTML=(err? '<span class="t-err">'+RQ.esc(err)+'</span>' : (out.length? RQ.esc(out.join('\n')) : '<span class="t-sys">(no output)</span>'));
          const ok=!err && JSON.stringify(out)===JSON.stringify(p5.expect);
          done(ok, ok? 'Your program produced the expected output.':(err? 'Fix the error and run again.' : 'Expected output: '+p5.expect.join(' | ')+'. Yours: '+(out.join(' | ')||'(nothing)')));
        };
      } else if(p5.type==='ps'){
        el.querySelector('#prac-check').onclick=()=>{
          const code=el.querySelector('#prac-code').value;
          const r=RQ.Pseudo.check(code, p5.must);
          done(r.pass, (r.pass? 'All required parts found and in order.' :
            'Missing or out of order: '+r.results.filter(x=>!x.ok).map(x=>'"'+x.frag+'"').join(', '))+' '+ (p5.hint?('Hint: '+RQ.esc(p5.hint)):''));
        };
      }
    } else if(s===6){
      const m=l.mission? RQ.missionById(l.mission):null;
      el.innerHTML=`<h2>🤖 Step 6 — Complete a mission</h2>
      ${m? `<div class="row" style="align-items:stretch">
        <div style="flex:1;min-width:240px"><div class="card" style="height:100%"><div class="row between"><h3>${m.icon||'🤖'} ${RQ.esc(m.title)}</h3><span class="chip am">${m.xp} XP</span></div>
        <p class="mt-s">${RQ.esc(m.brief)}</p>
        <p class="small dim">Topic: ${RQ.esc(m.topic)} · Difficulty ${'★'.repeat(m.difficulty)}</p>
        <button class="btn primary mt-s" onclick="RQ.go('mission','${m.id}')">Launch mission →</button></div></div>
        <div style="flex:1;min-width:240px"><div class="card" style="height:100%">
          <b class="small" style="color:var(--cy)">SUCCESS CRITERIA</b>
          <ul class="crit mt-s">${(m.instructions||[]).map(i=>'<li>'+RQ.esc(i)+'</li>').join('')}</ul>
          <p class="small dim mt-s">Complete the mission to earn its XP — then return and finish the knowledge test.</p>
        </div></div></div>`
      : `<p class="muted">This lesson\u2019s practice mission is free choice: open the <a href="#/missions">Mission Challenges</a> map and complete any unlocked mission to apply what you learned.</p>`}`;
      state.missionSeen=true; pr.step=Math.max(pr.step||1,6);
    } else if(s===7){
      el.innerHTML=`<h2>🧠 Step 7 — Knowledge test</h2>
        <p class="muted small">Answer all ${l.kc.length} questions correctly to complete the lesson. Wrong answers can be retried.</p>
        ${l.kc.map((q,i)=>`
          <div class="card mb-s" style="background:var(--panel2)" id="kc-${i}">
            <div class="quiz-q" style="font-size:.98rem">${i+1}. ${RQ.esc(q.q)}</div>
            <div class="row">${q.o.map((o,j)=>`<button class="btn ghost sm kc-opt" data-q="${i}" data-j="${j}">${RQ.esc(o)}</button>`).join('')}</div>
            <div class="small mt-s" id="kc-fb-${i}" style="min-height:18px"></div>
          </div>`).join('')}`;
      el.querySelectorAll('.kc-opt').forEach(b=>b.onclick=()=>{
        const qi=Number(b.dataset.q), j=Number(b.dataset.j), q=l.kc[qi];
        const fbEl=el.querySelector('#kc-fb-'+qi);
        if(state.kcAnswers[qi]!==undefined) return;
        if(j===q.a){
          state.kcAnswers[qi]=j; b.classList.add('btn');
          b.style.borderColor='var(--gr)'; b.style.color='var(--gr)';
          fbEl.innerHTML='<span style="color:var(--gr)">✓ Correct — '+RQ.esc(q.e)+'</span>';
          b.parentElement.querySelectorAll('.kc-opt').forEach(x=>x.disabled=true);
          save(); refreshDots();
          if(allKcCorrect()) RQ.toast('All correct — finish the lesson below!','good');
        } else {
          state.kcTried[qi]=(state.kcTried[qi]||0)+1;
          b.style.borderColor='var(--rd)'; b.style.color='var(--rd)';
          fbEl.innerHTML='<span style="color:var(--rd)">✗ Not right — '+RQ.esc(q.e)+'</span>';
          setTimeout(()=>{ b.style.borderColor=''; b.style.color=''; }, 1400);
          save();
        }
      });
    }
  }
  function refreshDots(){ render(); }
  render();
};
/* python runner used by lesson practice + code lab (robot api stubs: read_* return 2) */
function runLessonPy(src){
  const out=[];
  const it=RQ.Py.execute(RQ.Py.compile(src), {move_forward:1,move_backward:1,turn_left:1,turn_right:1,
    read_distance:1,read_light:1,read_line:1,read_touch:1,led_on:1,led_off:1,pick_up:1,drop_object:1,stop:1});
  let r;
  while(!(r=it.next()).done){
    const v=r.value;
    if(v&&v.print!==undefined) out.push(String(v.print));
    else if(v&&v.api){ it.next(v.api.indexOf('read_')===0?2:undefined); }
  }
  return out;
}
RQ.runLessonPy = runLessonPy;

/* ---------- profile ---------- */
RQ.views.profile = function(host,param,me){
  const p=RQ.DB.data.progress[me.id];
  host.innerHTML=`<div class="page-head"><div><div class="page-title">Your <span class="accent">Profile</span></div>
  <div class="page-sub">Avatar, name and data controls. Your year group is managed by your teacher.</div></div></div>
  <div class="grid g23">
    <div>
      <div class="card"><h3>Identity</h3>
        <div class="row mt-s"><div style="width:64px;height:64px" class="avatar-lg">${RQ.avatarSVG(me.avatar)}</div>
        <div><b>${RQ.esc(me.name)}</b><div class="small dim">Username: ${RQ.esc(me.username)} · ${RQ.isKidsUser(me)?RQ.KIDS_LEVELS[me.kidsLevel||1].name:'Year '+me.year}</div>
        <div class="small dim">Level ${RQ.Game.levelOf(p.stats.xp).lvl} · ${p.stats.xp} XP · ${p.stats.coins} coins</div></div></div>
        <div class="field mt"><label>Avatar colour</label><div class="avatar-grid">${RQ.AVATAR_COLORS.map(c=>`<div class="avatar-opt ${me.avatar.color===c?'sel':''}" data-c="${c}">${RQ.avatarSVG({color:c})}</div>`).join('')}</div></div>
        <div class="field"><label>Display name</label><input id="pf-name" value="${RQ.esc(me.name)}" maxlength="24"></div>
        <button class="btn primary sm" id="pf-save">Save profile</button>
      </div>
      <div class="card mt"><h3>${RQ.isKidsUser(me)?'🎓 My learning level':'Year group'}</h3>
        ${RQ.isKidsUser(me)?`
        <p class="muted small">You are a <b style="color:${RQ.KIDS_LEVELS[(RQ.Kids.P(me)&&RQ.Kids.P(me).kids.level)||me.kidsLevel||1].color}">${RQ.KIDS_LEVELS[(RQ.Kids.P(me)&&RQ.Kids.P(me).kids.level)||me.kidsLevel||1].name}</b> (ages ${RQ.KIDS_LEVELS[(RQ.Kids.P(me)&&RQ.Kids.P(me).kids.level)||me.kidsLevel||1].ages}).
        You move up a level by finishing every world of your current level — your teacher can also move you early.</p>
        <div class="row between mt-s"><div><b class="small">Parent access code</b>
          <div class="mono" style="font-size:1.4rem;letter-spacing:3px;color:var(--am)">${RQ.Kids.parentCodeFor(me)}</div>
          <p class="small dim">A parent can enter this code on the welcome page to see your progress (read-only, no editing).</p></div></div>`
        :`<p class="muted small">You are enrolled in <b>Year ${me.year} — ${RQ.YEAR_META[me.year].name}</b>. This determines your lessons, quizzes and missions.
        Only teachers can change a student\u2019s year group — ask yours if this looks wrong.</p>`}
      </div>
    </div>
    <div>
      <div class="card"><h3>💾 Progress safety (Local Mode)</h3>
        <p class="small muted">ROBOQUEST runs entirely in your browser: accounts and progress live in this browser\u2019s local storage. Export a backup file to keep your progress safe (e.g. before switching device) and import it anywhere.</p>
        <div class="row mt-s">
          <button class="btn ghost sm" id="pf-export">⬇ Export backup</button>
          <button class="btn ghost sm" id="pf-import">⬆ Import backup</button>
          <input type="file" id="pf-file" accept=".json" style="display:none">
        </div>
        <p class="small dim mt-s">Avoid clearing site data or private-browsing mode, or progress will be lost.</p>
      </div>
      <div class="card mt"><h3>🚪 Session</h3>
        <button class="btn danger sm" id="pf-logout">Log out</button>
        <p class="small dim mt-s">Logging out keeps your progress; it just locks the door behind you.</p>
      </div>
    </div>
  </div>`;
  host.querySelectorAll('.avatar-opt').forEach(el=>el.onclick=()=>{
    me.avatar={color:el.dataset.c}; RQ.DB.save(); RQ.toast('Avatar updated'); RQ.render();
  });
  host.querySelector('#pf-save').onclick=()=>{
    const v=host.querySelector('#pf-name').value.trim();
    if(v.length<2){ RQ.toast('Name too short','bad'); return; }
    me.name=v; RQ.DB.save(); RQ.toast('Profile saved'); RQ.render();
  };
  host.querySelector('#pf-export').onclick=()=>RQ.DB.export();
  host.querySelector('#pf-import').onclick=()=>host.querySelector('#pf-file').click();
  host.querySelector('#pf-file').onchange=e=>{
    const f=e.target.files[0]; if(!f) return;
    RQ.DB.import(f, err=>{ if(err) RQ.toast('Import failed: '+err,'bad'); else { RQ.toast('Backup imported — progress restored','good'); RQ.render(); } });
  };
  host.querySelector('#pf-logout').onclick=()=>RQ.Auth.logout();
};


/* ===== views2.js ===== */
/* ================= ROBOQUEST STUDENT VIEWS (part 2): quiz, missions, lab, gamification ================= */

/* ================= QUIZ ARENA ================= */
RQ.views.quiz = function(host,param,me){
  const topics=RQ.quizTopics(me.year);
  const p=RQ.DB.data.progress[me.id];
  host.innerHTML=`<div class="page-head"><div><div class="page-title">Quiz <span class="accent">Arena</span></div>
  <div class="page-sub">Year ${me.year} question bank — ${RQ.DATA.QUESTIONS.filter(q=>q.year===me.year).length} questions across ${topics.length} topics. Randomised order, instant explanations, XP for correct answers.</div></div></div>
  <div class="card mb"><div class="row between"><div><h3>⚙️ Match settings</h3>
    <p class="small dim">Timed mode adds a 45-second timer per question. Untimed is better for careful study.</p></div>
    <label class="chip" style="cursor:pointer"><input type="checkbox" id="q-timer" style="accent-color:#26d9f2"> ⏱ Timed mode</label></div></div>
  <div class="grid g2">
    <div class="card"><h3>🎯 Topic quizzes</h3><p class="small dim">Six random questions from one topic. Perfect after studying a unit.</p>
      <div class="grid mt-s" style="grid-template-columns:1fr 1fr">
      ${topics.map(t=>{ const count=RQ.questionsFor(me.year,t).length;
        const key='y'+me.year+'-'+t; const best=p.quizzes[key]&&p.quizzes[key].best;
        return `<div class="card hover" style="padding:12px" onclick="RQ.startQuiz('${RQ.esc(t)}')">
          <b style="font-size:.88rem">${RQ.esc(t)}</b>
          <div class="small dim mt-s">${count} questions ${best!=null? ' · best '+best+'%':''}</div></div>`;}).join('')}
      </div></div>
    <div><div class="card"><h3>👑 Full Challenge</h3>
      <p class="small dim">Ten random questions drawn from every Year ${me.year} topic. Higher XP, real bragging rights.</p>
      <button class="btn primary block mt-s" onclick="RQ.startQuiz('__full__')">⚔️ Enter the Full Challenge</button></div>
      <div class="card mt"><h3>📈 Your record</h3>
        <div class="row mt-s">
          <div class="center" style="flex:1"><div class="stat-num" style="color:var(--cy)">${p.stats.quizRuns}</div><div class="stat-lbl">Quizzes</div></div>
          <div class="center" style="flex:1"><div class="stat-num" style="color:var(--gr)">${p.stats.perfect}</div><div class="stat-lbl">Perfect runs</div></div>
        </div></div></div>
  </div>`;
};
RQ.startQuiz = function(topic){
  const me=RQ.Auth.user();
  const timed=document.getElementById('q-timer')?document.getElementById('q-timer').checked:false;
  const pool=RQ.questionsFor(me.year, topic==='__full__'?null:topic);
  if(pool.length<4){ RQ.toast('Not enough questions in this topic yet','bad'); return; }
  const count=topic==='__full__'?10:6;
  const qs=RQ.shuffle(pool).slice(0,Math.min(count,pool.length));
  RQ.sessionStore.set('rq_quiz', JSON.stringify({topic, timed, ids:qs.map(q=>q.id)}));
  RQ.go('quizrun');
};
RQ.views.quizrun = function(host){
  const cfg=JSON.parse(RQ.sessionStore.get('rq_quiz')||'null');
  const me=RQ.Auth.user();
  if(!cfg){ RQ.go('quiz'); return; }
  const all=RQ.questionsFor(me.year).concat(RQ.DATA.QUESTIONS);
  let qs=cfg.ids.map(id=>RQ.DATA.QUESTIONS.find(q=>q.id===id)).filter(Boolean);
  // per-question presentation state
  qs=qs.map(q=>{
    const view={q, opts:q.o?RQ.shuffle(q.o.map((o,i)=>({o,i}))):null,
      rightShuffled:q.pairs?RQ.shuffle(q.pairs.map((pr,i)=>({pr,i}))):null,
      itemsShuffled:q.items?RQ.shuffle(q.items.map((it,i)=>({it,i}))):null};
    return view;
  });
  let idx=0, correct=0, answered=false, timerId=null, timeLeft=0;
  const key=(cfg.topic==='__full__'?'full-y'+me.year:'y'+me.year+'-'+cfg.topic);
  function render(){
    if(idx>=qs.length){ return finish(); }
    answered=false;
    const v=qs[idx], q=v.q;
    let body='';
    if(q.type==='mc'){
      body=`<div id="q-opts">${v.opts.map((o,i)=>`<button class="opt" data-i="${o.i}"><span class="key">${'ABCD'[i]}</span>${RQ.esc(o.o)}</button>`).join('')}</div>`;
    } else if(q.type==='tf'){
      body=`<div class="tf-row" id="q-opts">
        <button class="opt" data-i="0"><span class="key">T</span> TRUE</button>
        <button class="opt" data-i="1"><span class="key">F</span> FALSE</button></div>`;
    } else if(q.type==='multi'){
      body=`<p class="small dim">Select ALL correct answers, then submit.</p>
      <div id="q-opts">${v.opts.map((o,i)=>`<button class="opt" data-i="${o.i}"><span class="key">☑</span>${RQ.esc(o.o)}</button>`).join('')}</div>
      <button class="btn primary sm mt-s" id="q-submit">Submit selection</button>`;
    } else if(q.type==='fill'){
      const parts=q.code.split(/_{3,}/);
      body=`<div class="codeblock mb-s"><pre>${parts.map((p,i)=> i<parts.length-1 ? RQ.esc(p)+'<input class="blank-input" data-blank="'+i+'" placeholder="...">' : RQ.esc(p)).join('')}</pre></div>
      <button class="btn primary sm" id="q-submit">Submit answers</button>`;
    } else if(q.type==='output'){
      body=`<div class="codeblock mb-s"><div class="hd"><span>python</span></div><pre>${RQ.highlight(q.code||'','python')}</pre></div>
      <div class="field"><label>Exact output</label><input id="q-out" class="mono" placeholder="type the program output"></div>
      <button class="btn primary sm" id="q-submit">Submit</button>`;
    } else if(q.type==='error'){
      const lines=(q.code||'').split('\n');
      body=`<div class="codeblock mb-s"><ol>${lines.map(l=>'<li>'+RQ.esc(l)+'</li>').join('')}</ol></div>
      <div id="q-opts">${q.o.map((o,i)=>`<button class="opt" data-i="${i}"><span class="key">${'ABCD'[i]}</span>${RQ.esc(o)}</button>`).join('')}</div>`;
    } else if(q.type==='order'){
      body=`<p class="small dim">Click the steps in the correct running order:</p>
      <div class="chip-seq mb-s" id="q-seq"></div>
      <div class="pool" id="q-pool">${v.itemsShuffled.map(it=>`<span class="seq-chip" data-i="${it.i}">${RQ.esc(it.it)}</span>`).join('')}</div>
      <button class="btn primary sm mt-s" id="q-submit">Submit order</button>`;
    } else if(q.type==='match'){
      body=`<p class="small dim">Click an item on the left, then its partner on the right:</p>
      <div class="match-grid">
        <div id="q-left">${q.pairs.map((pr,i)=>`<div class="match-item" data-l="${i}">${RQ.esc(pr[0])}</div>`).join('')}</div>
        <div id="q-right">${v.rightShuffled.map(r=>`<div class="match-item" data-r="${r.i}">${RQ.esc(r.pr[1])}</div>`).join('')}</div>
      </div><div class="small dim mt-s" id="q-pairs"></div>
      <button class="btn primary sm mt-s" id="q-submit">Submit pairs</button>`;
    }
    host.innerHTML=`<div class="page-head"><div><div class="page-title">Quiz <span class="accent">Battle</span></div>
      <div class="page-sub">${cfg.topic==='__full__'?'Full Challenge':RQ.esc(cfg.topic)} · Question ${idx+1} of ${qs.length} · Difficulty ${'★'.repeat(q.diff||1)}</div></div>
      <div class="row"><span class="chip gr">✓ ${correct}</span>${cfg.timed?'<span class="chip rd" id="q-timerchip">⏱ 45</span>':''}
      <button class="btn ghost sm" onclick="RQ.go('quiz')">Leave</button></div></div>
    <div class="card"><div class="quiz-q">${RQ.esc(q.q)}</div>${body}<div id="q-fb"></div></div>`;
    wire(q,v);
    if(cfg.timed) startTimer(q);
  }
  function startTimer(){
    timeLeft=45; clearInterval(timerId);
    const chip=()=>host.querySelector('#q-timerchip');
    timerId=setInterval(()=>{
      timeLeft--; const c=chip(); if(c) c.textContent='⏱ '+timeLeft;
      if(timeLeft<=0){ clearInterval(timerId); grade(null); }
    },1000);
  }
  function wire(q,v){
    const fb=host.querySelector('#q-fb');
    if(q.type==='multi'){
      const picked=new Set();
      host.querySelectorAll('#q-opts .opt').forEach(b=>b.onclick=()=>{
        if(answered) return;
        const i=Number(b.dataset.i);
        if(picked.has(i)){ picked.delete(i); b.classList.remove('sel'); }
        else { picked.add(i); b.classList.add('sel'); }
      });
      host.querySelector('#q-submit').onclick=()=>{
        const arr=[...picked].sort(); const want=q.a.slice().sort();
        const ok=arr.length===want.length && arr.every((x,i)=>x===want[i]);
        grade(ok, v.opts.filter(o=>want.includes(o.i)).map(o=>o.o).join(' · '));
      };
    } else if(q.type==='fill'){
      host.querySelector('#q-submit').onclick=()=>{
        const inputs=[...host.querySelectorAll('.blank-input')];
        const ok=inputs.every((inp,i)=>{
          const val=inp.value.trim().toLowerCase();
          return q.a[i].split('|').map(s=>s.trim().toLowerCase()).includes(val);
        });
        grade(ok, 'Answers: '+q.a.map(a=>a.split('|')[0]).join(', '));
      };
    } else if(q.type==='output'){
      host.querySelector('#q-submit').onclick=()=>{
        const raw=host.querySelector('#q-out').value;
        const norm=s=>String(s||'').replace(/\r/g,'').split('\n').map(l=>l.trim()).filter(l=>l!=='').join('\n');
        const want=norm(q.a), wantSp=want.replace(/\n/g,' ');
        const got=norm(raw), gotSp=got.replace(/\n/g,' ');
        grade(got===want||got===wantSp||gotSp===wantSp, 'Expected: '+q.a.replace(/\n/g,' ⏎ '));
      };
    } else if(q.type==='order'){
      const seq=[];
      host.querySelectorAll('#q-pool .seq-chip').forEach(c=>c.onclick=()=>{
        if(answered) return;
        seq.push(Number(c.dataset.i)); c.remove();
        renderSeq();
      });
      function renderSeq(){
        host.querySelector('#q-seq').innerHTML=seq.map((i,n)=>`<span class="seq-chip" style="background:linear-gradient(120deg,#0e7490,#22d3ee)">${n+1}. ${RQ.esc(q.items[i])} ✕</span>`).join('') || '<span class="dim small">click chips below…</span>';
        host.querySelectorAll('#q-seq .seq-chip').forEach((c,n)=>c.onclick=()=>{
          if(answered) return; const i=seq.splice(n,1)[0];
          const pool=host.querySelector('#q-pool');
          const sp=document.createElement('span'); sp.className='seq-chip'; sp.dataset.i=i; sp.textContent=q.items[i];
          pool.appendChild(sp); sp.onclick=()=>{ if(answered) return; seq.push(i); sp.remove(); renderSeq(); };
          renderSeq();
        });
      }
      host.querySelector('#q-submit').onclick=()=>{
        if(seq.length!==q.items.length){ RQ.toast('Place every step first','bad'); return; }
        grade(seq.every((v,i)=>v===i), 'Correct order: '+q.items.map((s,i)=>(i+1)+' '+s).join(' → '));
      };
    } else if(q.type==='match'){
      let pickedL=null; const pairsDone=[];
      host.querySelectorAll('#q-left .match-item').forEach(el=>el.onclick=()=>{
        if(answered||el.classList.contains('paired')) return;
        host.querySelectorAll('#q-left .match-item').forEach(x=>x.classList.remove('picked'));
        el.classList.add('picked'); pickedL=el;
      });
      host.querySelectorAll('#q-right .match-item').forEach(el=>el.onclick=()=>{
        if(answered||!pickedL||el.classList.contains('paired')) return;
        const li=Number(pickedL.dataset.l), ri=Number(el.dataset.r);
        pickedL.classList.remove('picked'); pickedL.classList.add('paired'); pickedL.dataset.r=ri;
        el.classList.add('paired'); pairsDone.push([li,ri]); pickedL=null;
        host.querySelector('#q-pairs').textContent=pairsDone.length+'/'+q.pairs.length+' paired';
      });
      host.querySelector('#q-submit').onclick=()=>{
        if(pairsDone.length<q.pairs.length){ RQ.toast('Pair every item first','bad'); return; }
        const ok=pairsDone.every(([l,r])=>l===r);
        grade(ok, 'Correct pairs: '+q.pairs.map(p=>p[0]+' → '+p[1]).join(' · '));
      };
    } else {
      host.querySelectorAll('#q-opts .opt').forEach(b=>b.onclick=()=>{
        if(answered) return;
        grade(Number(b.dataset.i)===(q.type==='tf'?q.a:q.a), q.type==='tf'? ('Correct answer: '+(q.a===0?'TRUE':'FALSE')) : q.o[q.a]);
      });
    }
    function grade(ok, reveal){
      if(answered) return; answered=true;
      clearInterval(timerId);
      if(ok) correct++;
      // mark visuals
      host.querySelectorAll('#q-opts .opt').forEach(b=>{
        b.disabled=true;
        const i=Number(b.dataset.i);
        const isAnswer=(q.type==='multi')? q.a.includes(i) : i===q.a;
        if(q.type==='mc'||q.type==='tf'||q.type==='error'){ if(isAnswer) b.classList.add('correct'); else if(b.classList.contains('sel')||(q.type!=='multi'&&!b.classList.contains('correct')&&b.onclick===undefined)) {} }
      });
      fb.innerHTML=`<div class="explain-box"><b>${ok?'✅ Correct! (+5 XP)':'❌ Not this time.'}</b> ${RQ.esc(reveal||'')}<br>${RQ.esc(q.e)}</div>
      <div class="row end mt"><button class="btn primary" id="q-next">${idx+1<qs.length?'Next question →':'See results →'}</button></div>`;
      host.querySelector('#q-next').onclick=()=>{ idx++; render(); };
    }
    RQ._grade=grade;
  }
  function finish(){
    clearInterval(timerId);
    const total=qs.length, pct=Math.round(correct/total*100);
    let xp=correct*5; let bonus=0;
    if(pct===100){ bonus=25; } else if(pct>=70){ bonus=20; }
    const db=RQ.DB.data, p=db.progress[me.id];
    const rec=p.quizzes[key]=p.quizzes[key]||{best:0,runs:0};
    const isBest=pct>rec.best; rec.best=Math.max(rec.best,pct); rec.runs++; rec.ts=Date.now();
    p.stats.quizRuns++; if(pct===100) p.stats.perfect++;
    db.quizAttempts.push({uid:me.id, key, topic:cfg.topic, year:me.year, score:correct, total, pct, ts:Date.now()});
    RQ.DB.save();
    if(xp+bonus>0) RQ.Game.award(me.id, xp+bonus, Math.round((xp+bonus)/2), 'Quiz complete: '+correct+'/'+total);
    const title=pct===100?'FLAWLESS VICTORY!':pct>=70?'Victory!':'Battle complete';
    host.innerHTML=`<div class="page-head"><div><div class="page-title">Quiz <span class="accent">Results</span></div></div>
      <button class="btn ghost sm" onclick="RQ.go('quiz')">← Arena</button></div>
    <div class="card center">
      <div class="big-ico" style="font-size:3.4rem">${pct===100?'💯':pct>=70?'🏆':'🛡️'}</div>
      <h2>${title}</h2>
      <div class="stat-num mt-s" style="font-size:2.6rem;color:var(--cy)">${correct}/${total}</div>
      <p class="muted">${pct}% accuracy ${isBest?'— <b style="color:var(--am)">new personal best!</b>':(rec.best? ' · best '+rec.best+'%':'')}</p>
      <p class="small dim">+${xp} XP for correct answers${bonus? ' · +'+bonus+' XP bonus':''} · attempts recorded for your teacher</p>
      <div class="row mt" style="justify-content:center">
        <button class="btn primary" onclick="RQ.startQuiz('${cfg.topic==='__full__'?'__full__':RQ.esc(cfg.topic).replace(/'/g,'')}')">🔁 Retry (new questions)</button>
        <button class="btn ghost" onclick="RQ.go('quiz')">Back to arena</button>
        <button class="btn ghost" onclick="RQ.go('dash')">Dashboard</button>
      </div>
    </div>
    <div class="card mt"><h3>Review</h3>
      ${qs.map((v,i)=>`<div class="row between" style="border-bottom:1px dashed var(--line);padding:8px 0">
        <span class="small muted">${i+1}. ${RQ.esc(v.q.q)}</span><span class="chip">${RQ.esc(v.q.topic||'')}</span></div>`).join('')}
    </div>`;
    RQ.confetti();
  }
  render();
};

/* ================= MISSIONS ================= */
RQ.views.missions = function(host,param,me){
  const p=RQ.DB.data.progress[me.id];
  const list=RQ.missionsFor(me.year);
  const custom=RQ.customMissionsFor(me.year);
  const bossDone=p.missions[list.filter(m=>m.boss)[0]?.id]?.done;
  const allDone=list.filter(m=>!m.boss).every(m=>p.missions[m.id]&&p.missions[m.id].done);
  host.innerHTML=`<div class="page-head"><div><div class="page-title">Mission <span class="accent">Challenges</span></div>
    <div class="page-sub">Year ${me.year} mission map — complete missions in order to unlock the next. Boss unlocks when all five are done.</div></div>
    <button class="btn ghost sm" onclick="RQ.go('lab')">🤖 Free-play in Code Lab</button></div>
  <div class="map-path">
    ${list.map(m=>{
      const pr=p.missions[m.id]||{};
      const unlocked=RQ.missionUnlocked(me,m);
      const stars=pr.stars||0;
      return `<div class="map-node">
        <div class="map-dot ${pr.done?'done':(unlocked?'next':'locked')}">${pr.done?'★':(m.boss?'👑':m.icon)}</div>
        <div class="card hover" style="flex:1;${unlocked?'':'opacity:.6'}" onclick="${unlocked?`RQ.go('mission','${m.id}')`:''}">
          <div class="row between"><h3>${RQ.esc(m.title)}</h3>
            <span class="chip ${pr.done?'gr':''}">${pr.done?'★'.repeat(stars)+'☆'.repeat(3-stars)+' done':(m.boss?'BOSS · '+m.xp+' XP':m.xp+' XP')}</span></div>
          <p>${RQ.esc(m.brief)}</p>
          <div class="row mt-s"><span class="chip">${RQ.esc(m.topic)}</span><span class="chip ${m.difficulty===3?'rd':m.difficulty===2?'am':'gr'}">${'★'.repeat(m.difficulty)} difficulty</span>
          <span class="chip">${m.lang==='python'?'🐍 Python':'🧩 Blocks/Code'}</span>
          ${unlocked?'':'<span class="chip">🔒 locked</span>'}</div>
        </div></div>`;}).join('')}
  </div>
  ${custom.length? `<h3 class="mt">🧑‍🏫 Teacher missions</h3><div class="grid auto mt-s">
    ${custom.map(m=>{const pr=p.missions[m.id]||{};return `<div class="card hover" onclick="RQ.go('mission','${m.id}')">
      <div class="row between"><h3 style="font-size:.95rem">${RQ.esc(m.title)}</h3><span class="chip ${pr.done?'gr':''}">${pr.done?'done':m.xp+' XP'}</span></div>
      <p class="small">${RQ.esc(m.brief||'Custom mission from your teacher')}</p></div>`;}).join('')}</div>`:''}`;
};

/* per-mission block-program persistence (session) */
RQ.sessionBlocks=(id,val)=>{ if(val===undefined){ try{ return JSON.parse(RQ.sessionStore.get('rq_blocks_'+id)||'null'); }catch(e){ return null; } }
  RQ.sessionStore.set('rq_blocks_'+id, JSON.stringify(val)); };

/* ---------- mission player ---------- */
RQ.views.mission = function(host, id, me){
  const m=RQ.missionById(id);
  if(!m){ host.innerHTML='<div class="empty-state">Mission not found. <a href="#/missions">Back to map</a></div>'; return; }
  const p=RQ.DB.data.progress[me.id];
  if(!RQ.missionUnlocked(me,m)){
    host.innerHTML=`<div class="empty-state"><div class="ico">🔒</div><h3>Mission locked</h3>
    <p class="muted">Complete the previous missions to unlock this one.${m.boss?' Boss missions need all five standard missions complete.':''}</p>
    <button class="btn primary mt" onclick="RQ.go('missions')">Back to mission map</button></div>`; return;
  }
  const lang=m.lang||'dsl';
  const pr=p.missions[m.id]=p.missions[m.id]||{};
  const savedProg=RQ.store.get('rq_prog_'+m.id)|| m.starter||'';
  const state={speed:1, mode:lang==='python'?'python':(lang==='blocks'?'blocks':(RQ.sessionBlocks(m.id)?'blocks':'code')), result:null};
  host.innerHTML=`<div class="page-head"><div><div class="page-title">${m.icon||'🤖'} ${RQ.esc(m.title)}</div>
    <div class="page-sub">${RQ.esc(m.topic)} · ${'★'.repeat(m.difficulty)} · Reward: ${m.xp} XP + coins ${m.boss?' · <b style="color:var(--am)">BOSS BATTLE</b>':''}</div></div>
    <button class="btn ghost sm" onclick="RQ.go('missions')">← Mission map</button></div>
  <div class="sim-layout">
    <div>
      <div class="sim-stage">
        <div class="sim-canvas-box" id="sim-box"></div>
        <div class="sense-bar" id="sense-bar"></div>
        <div class="sim-toolbar">
          <button class="btn primary sm" id="b-run">▶ Run</button>
          <button class="btn ghost sm" id="b-pause">⏸ Pause</button>
          <button class="btn ghost sm" id="b-step">⏭ Step</button>
          <button class="btn warn sm" id="b-reset">↺ Reset</button>
          <span class="sp"></span>
          <label class="small dim">Speed</label>
          <select class="speed-sel" id="b-speed"><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="1.5">1.5×</option><option value="2">2×</option><option value="4">4×</option></select>
        </div>
      </div>
      <div class="card mt" id="mission-result"></div>
    </div>
    <div>
      <div class="card mission-info">
        <h3>📋 Mission briefing</h3>
        <p>${RQ.esc(m.brief)}</p>
        <b class="small" style="color:var(--cy)">INSTRUCTIONS</b>
        <ul class="crit">${(m.instructions||[]).map(i=>'<li>'+RQ.esc(i)+'</li>').join('')}</ul>
        <b class="small" style="color:var(--cy)">OBJECTIVE</b>
        <p class="small muted" id="obj-line">${objectiveText(m)}</p>
        <b class="small" style="color:var(--cy)">MISSION CHECKLIST</b>
        <ul class="crit" id="crit-list">${(m.instructions||[]).map(()=> '<li>awaiting first run</li>').join('')}</ul>
        <div class="small dim">Par for 3★: ≤ ${m.par} moves, 0 bumps${lang==='python'&&m.requireFunctions?' · must define at least one function with def':''}</div>
      </div>
      <div class="card mt">
        <div class="row between mb-s"><h3>⌨️ Program</h3>
          ${m.allowBlocks? `<span class="tabs" style="margin:0"><span class="tab ${state.mode!=='blocks'?'on':''}" id="tab-code">Text</span><span class="tab ${state.mode==='blocks'?'on':''}" id="tab-blocks">🧩 Blocks</span></span>`:''}
        </div>
        <div id="editor-area"></div>
        <div class="row mt-s"><button class="btn ghost sm" id="b-clear">Clear editor</button><span class="sp"></span><span class="small dim" id="prog-hint"></span></div>
        <div class="terminal mt-s" id="py-console" style="display:${lang==='python'?'block':'none'};min-height:60px">// program output</div>
      </div>
      <div class="card mt"><h3>💡 Hints</h3>
        <div id="hint-area">${(m.hints||[]).map((h,i)=>`<div class="row between" style="border-bottom:1px dashed var(--line);padding:6px 0">
          <span class="small muted">Hint ${i+1}</span><button class="btn ghost xs" data-h="${i}">Reveal</button></div><div class="small muted" id="hint-${i}" style="display:none;padding:6px 0">${RQ.esc(h)}</div>`).join('')}</div>
      </div>
    </div>
  </div>`;
  // hints
  host.querySelectorAll('[data-h]').forEach(b=>b.onclick=()=>{
    host.querySelector('#hint-'+b.dataset.h).style.display='block'; b.remove();
  });
  // editor
  const editorArea=host.querySelector('#editor-area');
  function renderEditor(){
    if(state.mode==='blocks'){
      editorArea.innerHTML='<div id="blocks-ui"></div>';
      const bstate={root:RQ.sessionBlocks(m.id)||[], selected:null};
      RQ.renderBlocks(editorArea.querySelector('#blocks-ui'), bstate, ()=>{ RQ.sessionBlocks(m.id, bstate.root); });
      host.querySelector('#prog-hint').textContent='Blocks compile to the same robot language — press Run to execute.';
    } else {
      editorArea.innerHTML=`<div class="editor-wrap ${lang==='python'?'with-lines':''}"><div class="editor-lines" id="ed-lines"></div><textarea id="prog" spellcheck="false">${RQ.esc(savedProg)}</textarea></div>`;
      const ta=editorArea.querySelector('#prog');
      const upd=()=>{ if(lang==='python'){ const n=ta.value.split('\n').length;
        editorArea.querySelector('#ed-lines').innerHTML=Array.from({length:n},(_,i)=>i+1).join('<br>'); } };
      ta.addEventListener('input',()=>{ upd(); RQ.store.set('rq_prog_'+m.id, ta.value); });
      upd();
      host.querySelector('#prog-hint').textContent= lang==='python'
        ? 'Python API: move_forward(), move_backward(), turn_left(), turn_right(), read_distance(), read_light(), read_line(), read_touch(), led_on(), led_off(), pick_up(), drop_object(), stop() — plus print()'
        : 'Commands: MOVE_FORWARD, MOVE_BACKWARD, TURN_LEFT, TURN_RIGHT, REPEAT n [ ... ], IF cond [ ... ] ELSE [ ... ], WHILE cond [ ... ], ACTIVATE_LED ON/OFF, PICK_UP_OBJECT, DROP_OBJECT, READ_DISTANCE, STOP';
    }
  }
  function currentProgram(){
    // NOTE: for blocks mode, return the RAW block tree — Sim.compile() performs the
    // tree→executor conversion itself. Pre-converting here used to run toExecutor twice,
    // turning every block into a silent "say ?" no-op (robot never moved).
    if(state.mode==='blocks'){ return {text:RQ.sessionBlocks(m.id)||[], lang:'blocks'}; }
    const ta=host.querySelector('#prog');
    return {text:ta?ta.value:'', lang:lang==='python'?'python':'dsl'};
  }
  // simulator
  let sim=null;
  const sim0=new RQ.Sim(host.querySelector('#sim-box'), m, {
    onState:updateSensors, onEnd:onEnd, onError:onError,
    onConsole:(txt)=>{ const c=host.querySelector('#py-console'); if(c) c.textContent+=txt+'\n'; c.scrollTop=c.scrollHeight; }
  });
  sim=sim0;
  sim.setSpeed(1);
  host.querySelector('#b-speed').onchange=e=>{ sim.setSpeed(Number(e.target.value)); };
  host.querySelector('#b-reset').onclick=()=>{ sim.reset(); state.result=null; host.querySelector('#mission-result').innerHTML=''; const c=host.querySelector('#py-console'); if(c) c.textContent='// program output'; };
  host.querySelector('#b-pause').onclick=()=>{ if(sim.running){ sim.pause(); host.querySelector('#b-pause').textContent='▶ Resume'; } else { sim.paused=false; host.querySelector('#b-pause').textContent='⏸ Pause'; } };
  host.querySelector('#b-step').onclick=async()=>{
    const prog=currentProgram();
    if(!progReady(prog)) return;
    await sim.runOne();
  };
  host.querySelector('#b-run').onclick=async()=>{
    const prog=currentProgram();
    if(!progReady(prog)) return;
    const c=host.querySelector('#py-console'); if(c) c.textContent='// program output';
    await sim.run();
  };
  function progReady(prog){
    if(prog.lang==='blocks'){
      if(!prog.text.length){ RQ.toast('Your program is empty — add blocks first','bad'); return false; }
      const c=sim.compile(prog.text,'blocks');
      if(!c.ok){ RQ.toast(c.error,'bad'); return false; }
      return true;
    }
    const text=prog.text.trim();
    if(!text){ RQ.toast('Write a program first','bad'); return false; }
    if(prog.lang==='python' && m.requireFunctions && !/def\s+[A-Za-z_]\w*\s*\(/.test(text)){
      RQ.toast('Engineering standard: define at least one function with def','bad'); return false;
    }
    const c=sim.compile(text, prog.lang);
    if(!c.ok){ RQ.toast(c.error,'bad'); return false; }
    return true;
  }
  function updateSensors(s){
    const bar=host.querySelector('#sense-bar'); if(!bar||!s||!sim) return;
    const sn=s.sensors;
    bar.innerHTML=`
      <span class="sense ${sn.ahead?'hot':''}">📡 dist <b>${sn.distance}</b></span>
      <span class="sense ${sn.light?'hot':''}">💡 light <b>${sn.light?'ON':'off'}</b></span>
      <span class="sense ${sn.line?'hot':''}">🛤 line <b>${sn.line?'yes':'no'}</b></span>
      <span class="sense ${sn.touch?'hot':''}">🖐 touch <b>${sn.touch?'hit':'—'}</b></span>
      <span class="sense ${s.led?'hot':''}">🔦 LED <b>${s.led?'ON':'off'}</b></span>
      ${m.totalBoxes?`<span class="sense">📦 ${s.delivered}/${m.totalBoxes||sim.totalBoxes}</span>`:''}
      ${sim.totalEnergy?`<span class="sense">⚡ ${s.energy}/${sim.totalEnergy}</span>`:''}
      <span class="sense">👣 moves <b>${s.moves}</b></span><span class="sense" style="color:${s.bumps?'var(--rd)':'var(--mut)'}">💥 bumps <b>${s.bumps}</b></span>`;
    const crit=host.querySelector('#crit-list');
    if(crit) crit.innerHTML=criteriaHtml(m, s, sim);
  }
  function onEnd(res){
    if(res.type==='error'){ state.result={fail:true, message:res.message};
      host.querySelector('#mission-result').innerHTML=`<div class="err-msg">⚠️ Program error: ${RQ.esc(res.message)} — fix it and run again.</div>`; return; }
    if(res.type==='reset'){ return; }
    const db=RQ.DB.data, pr2=db.progress[me.id].missions[m.id]=db.progress[me.id].missions[m.id]||{};
    if(res.success){
      const first=!pr2.done;
      pr2.done=true; pr2.stars=Math.max(pr2.stars||0,res.stars); pr2.ts=Date.now(); pr2.moves=res.moves; pr2.bumps=res.bumps;
      db.missionAttempts.push({uid:me.id, mid:m.id, year:m.year, boss:!!m.boss, success:true, stars:res.stars, moves:res.moves, bumps:res.bumps, ts:Date.now()});
      RQ.DB.save();
      if(first) RQ.Game.award(me.id, m.xp, res.stars*25+(m.boss?50:0), 'Mission complete: '+m.title);
      else { p.stats.coins+=10; RQ.DB.save(); RQ.toast('Replay complete — +10 coins'); }
      state.result=res;
      host.querySelector('#mission-result').innerHTML=`
        <div class="center reward-pop"><div class="big-ico">${'⭐'.repeat(res.stars)}</div>
        <h2 style="color:var(--gr)">MISSION ${m.boss?'BOSS ':''}COMPLETE</h2>
        <p class="muted">${res.moves} moves · ${res.bumps} bumps · ${res.stars} stars${first? ' · +'+m.xp+' XP':''}</p>
        <p class="small dim" style="max-width:560px;margin:8px auto">${RQ.esc(m.explain||'')}</p>
        <div class="row mt" style="justify-content:center">
          <button class="btn ghost sm" onclick="document.querySelector('#b-reset').click()">↺ Run again</button>
          <button class="btn primary sm" onclick="RQ.go('missions')">🗺️ Next mission →</button>
        </div></div>`;
      RQ.confetti();
      RQ.beep.win();
    } else {
      db.missionAttempts.push({uid:me.id, mid:m.id, year:m.year, boss:!!m.boss, success:false, moves:res.moves, bumps:res.bumps, ts:Date.now()});
      RQ.DB.save();
      host.querySelector('#mission-result').innerHTML=`
        <div class="err-msg">🛑 Mission incomplete — the program finished without achieving the objective (${objectiveText(m).toLowerCase()}).
        ${res.bumps>1? ' You bumped '+res.bumps+' times — use your distance sensor to brake earlier.':''}</div>
        <div class="row between"><b class="small" style="color:var(--cy)">💡 Mission hints</b><span class="small dim">review the briefing, then adjust your program</span></div>
        ${(m.hints||[]).map(h=>'<p class="small muted">• '+RQ.esc(h)+'</p>').join('')}`;
    }
  }
  function onError(msg){ RQ.toast(msg,'bad'); }
  // Text ⇄ Blocks tabs — used to be decorative (no handlers): academy missions could
  // never switch to blocks mode. Wire them up now.
  const tabCode=host.querySelector('#tab-code'), tabBlocks=host.querySelector('#tab-blocks');
  function syncTabs(){
    if(!tabCode) return;
    tabCode.classList.toggle('on', state.mode!=='blocks');
    tabBlocks.classList.toggle('on', state.mode==='blocks');
  }
  if(tabCode) tabCode.onclick=()=>{ state.mode='code'; syncTabs(); renderEditor(); };
  if(tabBlocks) tabBlocks.onclick=()=>{ state.mode='blocks'; syncTabs(); renderEditor(); };
  renderEditor();
  syncTabs();
  updateSensors(sim.snapshot());
  function objectiveText(m){
    const t=(m.objective&&m.objective.type)||'reach';
    if(t==='reach') return 'Reach the target pad ◎';
    if(t==='collect_reach') return 'Collect ALL energy ⚡ then finish on the target ◎';
    if(t==='deliver') return 'Pick up every parcel 📦 and drop them on the pad P';
    if(t==='led_reach') return 'Switch the LED ON at a light zone, then finish on the target ◎';
    if(t==='led_on_light') return 'Stand on a light zone with the LED ON';
    if(t==='charge_reach') return 'Park on the charging station ⚡C';
    return 'Complete the objective';
  }
  function criteriaHtml(m,s,sim){
    const items=[];
    const t=(m.objective&&m.objective.type)||'reach';
    if(sim.totalEnergy) items.push(['Collect all energy ('+s.energy+'/'+sim.totalEnergy+')', s.energy>=sim.totalEnergy]);
    if(sim.totalBoxes) items.push(['Deliver all parcels ('+s.delivered+'/'+sim.totalBoxes+')', s.delivered>=sim.totalBoxes]);
    if(t==='led_reach'||m.ledRequired) items.push(['LED on at a light zone', s.led && sim.rt.ledAtLight]);
    items.push(['Finish on the required pad', (t==='deliver'? s.delivered>=sim.totalBoxes : sim.tileAt(s.x,s.y)===(t==='charge_reach'?'C':'T'))]);
    items.push(['No collisions (0 bumps so far)', s.bumps===0]);
    items.push(['Within par moves (≤'+m.par+')', s.moves<=m.par]);
    return items.map(i=>`<li class="${i[1]?'done':''}">${RQ.esc(i[0])}</li>`).join('');
  }
};

/* ================= CODE LAB ================= */
RQ.LAB_WORLDS={
  free:{name:'🧪 Free play bay', grid:['##########','#R.......#','#........#','#...E..T.#','#........#','##########'],startDir:'E',objective:{type:'collect_reach'},par:20},
  corridor:{name:'🚧 Corridor dodge', grid:['##########','#R..O...O#','#........#','#........#','##########'],startDir:'E',objective:{type:'reach'},par:24,
    brief:'Two crates block the fast lane — dodge them with IF OBSTACLE and reach the far corner.'},
  pickup:{name:'📦 Pickup & deliver', grid:['##########','#R..X....#','#.######.#','#.######P#','##########'],startDir:'E',objective:{type:'deliver'},par:18}
};
RQ.views.lab = function(host, modeParam, me){
  const mode=modeParam||'blocks';
  const tabs=[['blocks','🧩 Blocks'],['scratch','🐱 Scratch'],['pseudo','📝 Pseudocode'],['python','🐍 Python']];
  host.innerHTML=`<div class="page-head"><div><div class="page-title">Code <span class="accent">Lab</span></div>
    <div class="page-sub">Four ways to program: Scratch blocks, visual robot blocks, structured pseudocode, and the guided Python simulator. Your year: ${me.year}</div></div></div>
  <div class="tabs">${tabs.map(t=>`<span class="tab ${mode===t[0]?'on':''}" onclick="RQ.go('lab','${t[0]}')">${t[1]}</span>`).join('')}</div>
  <div id="lab-body"></div>`;
  const body=host.querySelector('#lab-body');
  if(mode==='blocks') renderBlocksLab(body, me);
  else if(mode==='scratch') renderScratchLab(body, me);
  else if(mode==='pseudo') renderPseudoLab(body, me);
  else renderPythonLab(body, me);
};

function renderBlocksLab(body, me){
  let worldKey=RQ.sessionStore.get('rq_lab_world')||'free';
  let sim=null;
  body.innerHTML=`<div class="sim-layout">
    <div><div class="sim-stage">
      <div class="row between mb-s"><span class="stat-lbl">World</span>
        <select class="speed-sel" id="lab-world">${Object.keys(RQ.LAB_WORLDS).map(k=>`<option value="${k}" ${worldKey===k?'selected':''}>${RQ.LAB_WORLDS[k].name}</option>`).join('')}</select></div>
      <div class="sim-canvas-box" id="lab-box"></div>
      <div class="sim-toolbar">
        <button class="btn primary sm" id="lb-run">▶ Run blocks</button>
        <button class="btn ghost sm" id="lb-step">⏭ Step</button>
        <button class="btn warn sm" id="lb-reset">↺ Reset</button>
        <span class="sp"></span><select class="speed-sel" id="lb-speed"><option value="1">1×</option><option value="2" selected>2×</option><option value="4">4×</option></select>
      </div>
      <div class="small dim mt-s" id="lab-brief">${RQ.esc(RQ.LAB_WORLDS[worldKey].brief||'Experiment freely: build any program with blocks and watch the robot follow it exactly.')}</div>
    </div></div>
    <div><div class="card"><h3>🧩 Block program</h3>
      <div id="lab-blocks"></div>
      <div class="err-msg mt-s" id="lab-err" style="display:none"></div>
    </div></div></div>`;
  const bstate={root:JSON.parse(RQ.sessionStore.get('rq_lab_blocks')||'[]'), selected:null};
  function mount(){ RQ.renderBlocks(body.querySelector('#lab-blocks'), bstate, ()=>{ RQ.sessionStore.set('rq_lab_blocks', JSON.stringify(bstate.root)); }); }
  function startSim(){
    const w=RQ.LAB_WORLDS[worldKey];
    if(sim) sim.destroy();
    sim=new RQ.Sim(body.querySelector('#lab-box'), w, { onEnd(res){
      if(res.type==='end'&&res.success){ RQ.toast('World complete! +15 XP practice','good');
        const db=RQ.DB.data, p=db.progress[me.id]; p.stats.blockRuns++;
        RQ.Game.award(me.id, 15, 10, 'Block world complete'); RQ.DB.save(); }
    }});
    sim.setSpeed(2);
    body.querySelector('#lab-brief').textContent=RQ.LAB_WORLDS[worldKey].brief||'Experiment freely: build any program with blocks and watch the robot follow it exactly.';
  }
  body.querySelector('#lab-world').onchange=e=>{ worldKey=e.target.value; RQ.sessionStore.set('rq_lab_world', worldKey); startSim(); };
  body.querySelector('#lb-run').onclick=async()=>{
    if(!bstate.root.length){ RQ.toast('Add some blocks first','bad'); return; }
    const nodes=RQ.Blocks.toExecutor(bstate.root);
    const c=sim.compile(nodes,'blocks');
    const errEl=body.querySelector('#lab-err');
    if(!c.ok){ errEl.textContent=c.error; errEl.style.display='block'; return; }
    errEl.style.display='none';
    const db=RQ.DB.data, p=db.progress[me.id]; p.stats.blockRuns++; RQ.DB.save();
    await sim.run();
  };
  body.querySelector('#lb-step').onclick=async()=>{ if(!bstate.root.length){ RQ.toast('Add blocks first','bad'); return; } sim.compile(RQ.Blocks.toExecutor(bstate.root),'blocks'); await sim.runOne(); };
  body.querySelector('#lb-reset').onclick=()=>sim.reset();
  body.querySelector('#lb-speed').onchange=e=>sim.setSpeed(Number(e.target.value));
  mount(); startSim();
}


function renderScratchLab(body, me){
  let sim=null;
  body.innerHTML=`<div class="sim-layout">
    <div><div class="sim-stage">
      <div class="row between mb-s"><span class="stat-lbl">Scratch stage · 480 × 360 · sprite 🐱</span>
        <select class="speed-sel" id="sc-speed"><option value="1">1×</option><option value="2" selected>2×</option><option value="4">4×</option></select></div>
      <div class="sim-canvas-box" id="sc-box"></div>
      <div class="sim-toolbar">
        <button class="btn primary sm" id="sc-run">⚑ Go</button>
        <button class="btn warn sm" id="sc-stop">⏹ Stop</button>
        <button class="btn ghost sm" id="sc-reset">↺ Reset</button>
        <span class="sp"></span><span class="chip">🐱 Scratch-style blocks</span>
      </div>
      <div class="small dim mt-s">Stack blocks under the <b>when ⚑ clicked</b> hat like in Scratch. Motion uses the Scratch stage coordinates (x: −240…240, y: −180…180, direction 90 = right).</div>
    </div></div>
    <div><div class="card"><h3>🐱 Scratch program</h3>
      <div class="sc-hat">⚑ when 🚩 clicked</div>
      <div id="sc-blocks"></div>
      <div class="err-msg mt-s" id="sc-err" style="display:none"></div>
    </div></div></div>`;
  const bstate={root:JSON.parse(RQ.sessionStore.get('rq_scratch_blocks')||'[]'), selected:null};
  function mount(){ RQ.renderBlocks(body.querySelector('#sc-blocks'), bstate, ()=>{ RQ.sessionStore.set('rq_scratch_blocks', JSON.stringify(bstate.root)); }, RQ.ScratchDefs); }
  function startStage(){ if(sim) sim.stop(); sim=new RQ.ScratchStage(body.querySelector('#sc-box')); sim.setSpeed(2); }
  body.querySelector('#sc-run').onclick=async()=>{
    if(!bstate.root.length){ RQ.toast('Add some Scratch blocks first','bad'); return; }
    const nodes=RQ.ScratchBlocks.toExecutor(bstate.root);
    const errEl=body.querySelector('#sc-err');
    errEl.style.display='none';
    const db=RQ.DB.data, p=db.progress[me.id]; p.stats.scratchRuns=(p.stats.scratchRuns||0)+1;
    if(!p.lessons['scratch-first']){ p.lessons['scratch-first']={done:true,ts:Date.now()};
      RQ.Game.award(me.id,10,5,'First Scratch program run'); RQ.toast('First Scratch program! +10 XP','good'); }
    RQ.DB.save();
    await sim.run(nodes, ()=>{ RQ.toast('Scratch program finished 🐱','good'); });
  };
  body.querySelector('#sc-stop').onclick=()=>sim.stop();
  body.querySelector('#sc-reset').onclick=()=>{ sim.reset(); body.querySelector('#sc-err').style.display='none'; };
  body.querySelector('#sc-speed').onchange=e=>sim.setSpeed(Number(e.target.value));
  mount(); startStage();
}

function renderPseudoLab(body, me){
  const sets=RQ.DATA.PSEUDO.filter(p=>p.year<=me.year);
  let current=sets[0];
  let attempts=0;
  body.innerHTML=`<div class="sim-layout" style="grid-template-columns:320px 1fr">
    <div class="card"><h3>📝 Exercises</h3><p class="small dim">Practise structured English plans. The checker looks for required keywords in order.</p>
      <div class="mt-s" id="ps-list">${sets.map(s=>`<div class="card hover" style="padding:10px;margin-bottom:8px" data-id="${s.id}">
        <b class="small">${RQ.esc(s.title)}</b><div class="small dim">Year ${s.year}+ · ${s.must.length} required parts</div></div>`).join('')}</div>
      <div class="divider"></div>
      <b class="small" style="color:var(--cy)">REFERENCE</b>
      <div class="codeblock mt-s"><pre>START
  SET x TO 0
  IF cond THEN
    ...
  ELSE
    ...
  ENDIF
  REPEAT n TIMES
    ...
  END REPEAT
  WHILE cond
    ...
  END WHILE
  DISPLAY x
END</pre></div></div>
    <div id="ps-work"></div></div>`;
  function pick(id){ current=sets.find(s=>s.id===id); attempts=0; renderWork(); }
  function renderWork(){
    const w=body.querySelector('#ps-work');
    w.innerHTML=`<div class="card"><div class="row between"><h3>${RQ.esc(current.title)}</h3><span class="chip">${current.xp||40} XP</span></div>
      <p class="muted mt-s">${RQ.esc(current.brief)}</p>
      <div class="field mt-s"><label>Your pseudocode</label><textarea id="ps-code" spellcheck="false" style="min-height:200px">${RQ.esc(current.starter||'')}</textarea></div>
      <div class="row"><button class="btn primary sm" id="ps-check">✓ Check pseudocode</button>
      <button class="btn ghost sm" id="ps-reveal" style="display:none">👁 Reveal example (${2-attempts} attempts left)</button></div>
      <div id="ps-fb"></div>
      <div class="mt-s"><b class="small" style="color:var(--cy)">REQUIRED PARTS (in order)</b>
        <div class="row mt-s" id="ps-frags">${current.must.map(m=>`<span class="chip mono">${RQ.esc(m)}</span>`).join('')}</div></div>
    </div>`;
    body.querySelectorAll('#ps-list .card').forEach(el=>el.onclick=()=>pick(el.dataset.id));
    body.querySelector('#ps-check').onclick=()=>{
      const code=body.querySelector('#ps-code').value;
      const r=RQ.Pseudo.check(code, current.must);
      attempts++;
      const fb=body.querySelector('#ps-fb');
      fb.innerHTML=`<div class="explain-box mt-s"><b>${r.pass?'✅ Complete pseudocode!':'❌ '+r.okCount+'/'+r.total+' required parts found (in order).'}</b>
        ${r.pass? 'Your plan contains every required keyword in the right order — this is exactly how exam answers are marked.'
          : 'Missing or misplaced: '+r.results.filter(x=>!x.ok).map(x=>'<span class="mono">'+RQ.esc(x.frag)+'</span>').join(', ')}</div>`;
      const p=RQ.DB.data.progress[me.id];
      if(r.pass && !p.lessons['ps-'+current.id]){
        p.lessons['ps-'+current.id]={done:true,ts:Date.now()};
        RQ.DB.save(); RQ.Game.award(me.id, current.xp||40, Math.round((current.xp||40)/4), 'Pseudocode solved: '+current.title);
      }
      if(attempts>=2 && !r.pass) body.querySelector('#ps-reveal').style.display='';
    };
    body.querySelector('#ps-reveal').onclick=()=>{
      body.querySelector('#ps-code').value=current.solution;
      RQ.toast('Example revealed — study it, then write your own version');
    };
  }
  renderWork();
}

function renderPythonLab(body, me){
  const all=RQ.DATA.CHALLENGES.filter(c=>c.mode==='python'&&c.year<=me.year);
  const custom=RQ.DB.data.customChallenges.filter(c=>Number(c.year)===Number(me.year));
  const list=all.concat(custom);
  let current=null;
  body.innerHTML=`<div class="sim-layout" style="grid-template-columns:320px 1fr">
    <div class="card"><h3>🐍 Python challenges</h3>
      <p class="small dim">Write real Python (guided simulator: variables, maths, if/for/while, functions, lists, print — no file or network access). Output is checked automatically.</p>
      <div class="mt-s" id="ch-list">
        <div class="card hover" style="padding:10px;margin-bottom:8px" data-id="__free__"><b class="small">🧪 Free editor</b><div class="small dim">code anything, run it, see output</div></div>
        ${list.map(c=>`<div class="card hover" style="padding:10px;margin-bottom:8px" data-id="${c.id}">
          <b class="small">${c.custom?'🧑‍🏫 ':''}${RQ.esc(c.title)}</b><div class="small dim">Year ${c.year} · ${c.xp} XP</div></div>`).join('')}
      </div></div>
    <div id="py-work"></div></div>`;
  function pick(id){
    current = id==='__free__'? {id:'__free__', title:'Free editor', brief:'Write any Python you like and press Run.', starter:'# your Python playground\nprint("Hello ROBOQUEST")\n', xp:0} :
      list.find(c=>c.id===id);
    attempts=0; renderWork();
  }
  let attempts=0;
  function renderWork(){
    const w=body.querySelector('#py-work');
    w.innerHTML=`<div class="card"><div class="row between"><h3>${current.custom?'🧑‍🏫 ':''}${RQ.esc(current.title)}</h3>${current.xp?`<span class="chip">${current.xp} XP</span>`:''}</div>
      <p class="muted mt-s">${RQ.esc(current.brief)}</p>
      <div class="editor-wrap mt-s"><div class="editor-lines" id="py-lines"></div><textarea id="py-code" spellcheck="false" style="min-height:220px">${RQ.esc(current.starter||'')}</textarea></div>
      <div class="row mt-s"><button class="btn primary sm" id="py-run">▶ Run</button>
        <button class="btn warn sm" id="py-reset">↺ Starter</button>
        ${current.expect&&current.expect.length? '<span class="chip cy">expected output: '+current.expect.map(e=>RQ.esc(e)).join(' ⏎ ')+'</span>':''}
        <span class="sp"></span><button class="btn ghost sm" id="py-reveal" style="display:none">👁 Example solution</button></div>
      <div class="terminal mt-s" id="py-out">// output appears here</div>
      <div id="py-fb"></div></div>`;
    body.querySelectorAll('#ch-list .card').forEach(el=>el.onclick=()=>pick(el.dataset.id));
    const ta=w.querySelector('#py-code');
    const upd=()=>{ w.querySelector('#py-lines').innerHTML=Array.from({length:ta.value.split('\n').length},(_,i)=>i+1).join('<br>'); };
    ta.addEventListener('input',upd); upd();
    w.querySelector('#py-reset').onclick=()=>{ ta.value=current.starter||''; upd(); };
    w.querySelector('#py-run').onclick=()=>{
      attempts++;
      const term=w.querySelector('#py-out'); const fb=w.querySelector('#py-fb');
      let out=[], err=null;
      try{ out=runLessonPy(ta.value); }catch(e){ err=e.message; }
      term.innerHTML= err? '<span class="t-err">'+RQ.esc(err)+'</span>' : (out.length? RQ.esc(out.join('\n')) : '<span class="t-sys">(program ran — no output)</span>');
      const db=RQ.DB.data, p=db.progress[me.id]; p.stats.codeRuns++; p.stats.pyRuns++; RQ.DB.save();
      const isChallenge=current.expect&&current.expect.length;
      if(err){ fb.innerHTML='<div class="err-msg mt-s">Runtime error — read the message and fix line by line.</div>'; if(attempts>=2&&current.solution) w.querySelector('#py-reveal').style.display=''; return; }
      if(!isChallenge){ fb.innerHTML='<div class="ok-msg mt-s">Ran cleanly ✓ ('+out.length+' output line'+(out.length===1?'':'s')+')</div>'; return; }
      const norm=s=>String(s).replace(/\r/g,'').trim();
      const ok=JSON.stringify(out.map(norm))===JSON.stringify(current.expect.map(norm));
      fb.innerHTML= ok? '<div class="ok-msg mt-s">✅ Correct output — challenge complete!</div>'
        : '<div class="err-msg mt-s">❌ Expected: '+current.expect.map(e=>RQ.esc(e)).join(' ⏎ ')+' — you printed: '+(out.map(e=>RQ.esc(e)).join(' ⏎ ')||'(nothing)')+'</div>';
      if(ok && current.id!=='__free__' && !p.lessons['py-'+current.id]){
        p.lessons['py-'+current.id]={done:true,ts:Date.now()}; RQ.DB.save();
        RQ.Game.award(me.id, current.xp, Math.round(current.xp/4), 'Challenge complete: '+current.title);
      }
      if(!ok && attempts>=2 && current.solution) w.querySelector('#py-reveal').style.display='';
    };
    w.querySelector('#py-reveal').onclick=()=>{ ta.value=current.solution; upd(); RQ.toast('Example loaded — study it, change it, make it yours'); };
  }
  pick('__free__');
}

/* ================= ACHIEVEMENTS ================= */
RQ.views.achievements = function(host,param,me){
  const p=RQ.DB.data.progress[me.id];
  const defs=RQ.Game.badgeDefs(me);
  const earned=defs.filter(d=>p.badges.includes(d.id));
  host.innerHTML=`<div class="page-head"><div><div class="page-title">Achievement <span class="accent">Centre</span></div>
  <div class="page-sub">${earned.length}/${defs.length} badges earned — badges are awarded automatically as you learn.</div></div></div>
  <div class="grid auto">
    ${defs.map(d=>{ const has=p.badges.includes(d.id);
      return `<div class="card badge-card ${has?'earned':'locked'}"><div class="badge-ico">${d.icon}</div>
      <b>${d.name}</b><small>${d.desc}</small>${has?'<div class="chip gr mt-s">earned</div>':''}</div>`;}).join('')}
  </div>
  <div class="card mt"><h3>🎖️ Levels</h3><div class="grid g4 mt-s">
    ${RQ.LEVELS.map(L=>`<div class="card center" style="padding:12px;${p.stats.xp>=L.xp?'border-color:var(--cy)':''}">
      <b style="color:${p.stats.xp>=L.xp?'var(--cy)':'var(--dim)'}">Lv ${L.lvl}</b><div class="small ${p.stats.xp>=L.xp?'':'dim'}">${L.name}</div>
      <div class="small dim">${L.xp} XP</div></div>`).join('')}
  </div></div>`;
};

/* ================= LEADERBOARD ================= */
RQ.views.leaderboard = function(host,param,me){
  const db=RQ.DB.data;
  let scope='all', range='alltime';
  function render(){
    let students=db.users.filter(u=>u.role==='student');
    const pub=db.settings.leaderboardPublic;
    if(!pub){ students=students.filter(u=>u.id===me.id); }
    let rows=students.map(u=>{
      const p=db.progress[u.id]||{stats:{xp:0},xpWeek:{amount:0}};
      return {u, xp:range==='weekly'?(p.xpWeek&&p.xpWeek.key===RQ.weekKey()?p.xpWeek.amount:0):p.stats.xp, level:RQ.Game.levelOf(p.stats.xp).lvl};
    }).sort((a,b)=>b.xp-a.xp);
    if(scope!=='all') rows=rows.filter(r=>r.u.year===scope);
    host.innerHTML=`<div class="page-head"><div><div class="page-title">School <span class="accent">Leaderboard</span></div>
      <div class="page-sub">${pub?'Live rankings across the school.':'Public rankings are currently disabled by your teacher — showing only your own position.'}</div></div></div>
    <div class="row mb"><span class="stat-lbl" style="margin-right:6px">SCOPE</span>
      ${['all','8','9','10','11'].map(s=>`<span class="tab ${String(scope)===s?'on':''}" data-scope="${s}">${s==='all'?'🏫 Whole school':'Year '+s}</span>`).join('')}
      <span class="stat-lbl" style="margin:0 6px">RANGE</span>
      <span class="tab ${range==='alltime'?'on':''}" data-range="alltime">All-time XP</span>
      <span class="tab ${range==='weekly'?'on':''}" data-range="weekly">This week</span></div>
    <div id="lb-rows">
      ${rows.length? rows.map((r,i)=>`
        <div class="lb-row ${r.u.id===me.id?'me':''}">
          <div class="lb-rank ${i<3?'r'+(i+1):''}">${i+1}</div>
          <div class="avatar-sm">${RQ.avatarSVG(r.u.avatar)}</div>
          <div class="lb-name">${RQ.esc(r.u.name)} ${r.u.demo?'<span class="chip">demo</span>':''}${r.u.id===me.id?'<span class="chip cy">you</span>':''}
            <small>Year ${r.u.year} · Lv ${r.level} ${RQ.esc(RQ.Game.levelOf((db.progress[r.u.id]||{stats:{xp:0}}).stats.xp).name)}</small></div>
          <span class="chip cy">⚡ ${r.xp} XP</span>
        </div>`).join('')
      : '<div class="empty-state"><div class="ico">🏅</div>No students ranked here yet — earn XP to appear!</div>'}
    </div>`;
    host.querySelectorAll('[data-scope]').forEach(el=>el.onclick=()=>{ scope=el.dataset.scope==='all'?'all':Number(el.dataset.scope); render(); });
    host.querySelectorAll('[data-range]').forEach(el=>el.onclick=()=>{ range=el.dataset.range; render(); });
  }
  render();
};

/* ================= DAILY CHALLENGE ================= */
RQ.views.daily = function(host,param,me){
  const today=RQ.todayKey();
  const bank=RQ.DATA.DAILY;
  const pick=bank[RQ.hashPick(today+':'+me.year, bank.length)];
  const p=RQ.DB.data.progress[me.id];
  const done=p.daily&&p.daily.date===today;
  let answered=false;
  host.innerHTML=`<div class="page-head"><div><div class="page-title">Daily <span class="accent">Challenge</span></div>
    <div class="page-sub">${today} · A fresh question every day. Rewards: 30 XP + 15 coins · keeps your streak alive!</div></div></div>
  <div class="card" style="max-width:640px;margin:0 auto">
    <div class="row between"><span class="chip am">🔥 streak: ${p.streak.count} day${p.streak.count===1?'':'s'}</span>
      <span class="chip cy">${p.stats.dailyDone} completed all-time</span></div>
    ${done? `<div class="center mt"><div class="big-ico">✅</div><h3>Today\u2019s challenge complete!</h3>
        <p class="muted">Come back tomorrow for a new challenge. Streaks grow when you show up daily.</p>
        <button class="btn ghost mt-s" onclick="RQ.go('dash')">Back to dashboard</button></div>`
    : `<div class="quiz-q mt">⚡ ${RQ.esc(pick.q)}</div>
       <div id="d-opts">${pick.o.map((o,i)=>`<button class="opt" data-i="${i}"><span class="key">${'ABCD'[i]}</span>${RQ.esc(o)}</button>`).join('')}</div>
       <div id="d-fb"></div>`}
  </div>`;
  if(!done){
    host.querySelectorAll('#d-opts .opt').forEach(b=>b.onclick=()=>{
      if(answered) return; answered=true;
      const i=Number(b.dataset.i), ok=i===pick.a;
      host.querySelectorAll('#d-opts .opt').forEach(x=>{x.disabled=true; if(Number(x.dataset.i)===pick.a) x.classList.add('correct'); else if(Number(x.dataset.i)===i) x.classList.add('wrong');});
      const p2=RQ.DB.data.progress[me.id];
      p2.daily={date:today, ok}; p2.stats.dailyDone++;
      RQ.DB.save();
      host.querySelector('#d-fb').innerHTML=`<div class="explain-box"><b>${ok?'✅ Correct!':'❌ The answer was: '+RQ.esc(pick.o[pick.a])+'.'}</b> ${RQ.esc(pick.e)}</div>
      <div class="center mt"><button class="btn primary" onclick="RQ.go('dash')">Collect reward & continue →</button></div>`;
      RQ.Game.award(me.id, 30, 15, ok? 'Daily challenge aced!':'Daily challenge complete');
      if(ok) RQ.confetti();
    });
  }
};


/* ===== views3.js ===== */
/* ================= ROBOQUEST TEACHER VIEWS ================= */
RQ.isTeacherOf = (t, studentId) => {
  const db=RQ.DB.data;
  const myClasses=db.classes.filter(c=>c.teacherId===t.id).map(c=>c.id);
  return db.memberships.some(m=>m.classId && myClasses.includes(m.classId) && m.studentId===studentId);
};
RQ.teacherStudents = t => {
  const db=RQ.DB.data;
  return db.users.filter(u=>u.role==='student');
};
function classAvgQuiz(db, studentIds){
  const at=db.quizAttempts.filter(a=>studentIds.includes(a.uid));
  return at.length? Math.round(at.reduce((s,a)=>s+a.pct,0)/at.length) : null;
}

/* ---------- overview ---------- */
RQ.views['t-dash'] = function(host,param,me){
  const db=RQ.DB.data;
  const students=db.users.filter(u=>u.role==='student');
  const active=students.filter(u=>{ const p=db.progress[u.id]; return p && p.lastActive && RQ.daysSince(p.lastActive)<=7; }).length;
  const avg=classAvgQuiz(db, students.map(s=>s.id));
  const missionsDone=db.missionAttempts.filter(a=>a.success).length;
  const myClasses=db.classes.filter(c=>c.teacherId===me.id);
  const lessonPct=(()=>{
    let done=0,total=0;
    students.forEach(u=>{ const ls=RQ.lessonsFor(u.year); const p=db.progress[u.id]; if(!p) return;
      ls.forEach(l=>{ total++; if(p.lessons[l.id]&&p.lessons[l.id].done) done++; }); });
    return total? Math.round(done/total*100):0;
  })();
  // support list: students inactive 7+ days or avg < 50
  const support=students.filter(u=>{
    const p=db.progress[u.id]; if(!p) return false;
    const a=classAvgQuiz(db,[u.id]);
    return (p.lastActive && RQ.daysSince(p.lastActive)>7) || (a!==null && a<50);
  }).slice(0,8);
  // topic difficulty: avg pct per topic from attempts
  const topicStats={};
  db.quizAttempts.forEach(a=>{ if(a.topic==='__full__') return;
    topicStats[a.topic]=topicStats[a.topic]||{sum:0,n:0};
    topicStats[a.topic].sum+=a.pct; topicStats[a.topic].n++; });
  const topics=Object.keys(topicStats).slice(0,8);
  host.innerHTML=`<div class="page-head"><div><div class="page-title">Teacher <span class="accent">Overview</span></div>
    <div class="page-sub">Welcome, ${RQ.esc(me.name)} — school-wide performance at a glance.</div></div>
    <button class="btn primary sm" onclick="RQ.go('t-classes')">👥 Manage classes</button></div>
  <div class="grid g4">
    <div class="card center"><div class="stat-num glow-cy">${students.length}</div><div class="stat-lbl">Registered students</div></div>
    <div class="card center"><div class="stat-num" style="color:var(--gr)">${active}</div><div class="stat-lbl">Active (7 days)</div></div>
    <div class="card center"><div class="stat-num" style="color:var(--am)">${avg===null?'—':avg+'%'}</div><div class="stat-lbl">Average quiz score</div></div>
    <div class="card center"><div class="stat-num" style="color:var(--pk)">${missionsDone}</div><div class="stat-lbl">Missions completed</div></div>
  </div>
  <div class="grid g23 mt">
    <div class="card"><h3>📊 Quiz score by topic (school average)</h3>
      ${topics.length? '<canvas class="chart" id="ch-topics" height="280"></canvas><p class="small dim mt-s">Lower bars flag difficult topics — consider assigning their lessons.</p>'
        : '<p class="dim small mt-s">No quiz attempts recorded yet. Once students take quizzes, topic averages appear here.</p>'}
      <div class="divider"></div><h3>🎓 Lesson completion rate</h3>
      <div class="row mt-s"><div style="width:130px">${RQ.donut(lessonPct,'#26d9f2')}</div>
        <div><b class="stat-num">${lessonPct}%</b><p class="small dim">of all year-group lessons completed by all students</p></div></div>
    </div>
    <div>
      <div class="card"><h3>🚨 Students needing support</h3>
        ${support.length? support.map(u=>{ const p=db.progress[u.id];
          return `<div class="row between" style="border-bottom:1px dashed var(--line);padding:8px 0">
            <span><b class="small">${RQ.esc(u.name)}</b> <span class="chip">Y${u.year}</span>
            <span class="small dim">· last active ${p.lastActive? RQ.daysSince(p.lastActive)+'d ago':'never'}</span></span>
            <button class="btn ghost xs" onclick="RQ.go('t-reports')">Report</button></div>`;}).join('')
          : '<p class="dim small">Nobody flagged — the cohort looks healthy.</p>'}
      </div>
      <div class="card mt"><h3>👥 My classes (${myClasses.length})</h3>
        ${myClasses.length? myClasses.map(c=>{ const mem=db.memberships.filter(m=>m.classId===c.id).length;
          return `<div class="row between" style="border-bottom:1px dashed var(--line);padding:8px 0">
            <span><b class="small">${RQ.esc(c.name)}</b> <span class="chip cy mono">${c.code}</span></span>
            <span class="small dim">${mem} students</span></div>`;}).join('')
          : '<p class="dim small">No classes yet — create one in Class Manager and share the join code.</p>'}
        <button class="btn ghost sm mt-s" onclick="RQ.go('t-classes')">Open class manager →</button>
      </div>
    </div>
  </div>
  <div class="card mt"><h3>📝 Recent quiz attempts</h3><div class="tbl-wrap"><table class="tbl">
    <tr><th>Student</th><th>Quiz</th><th>Year</th><th>Score</th><th>When</th></tr>
    ${db.quizAttempts.slice(-8).reverse().map(a=>{ const u=db.users.find(x=>x.id===a.uid);
      return `<tr><td><b>${u?RQ.esc(u.name):'?'}</b></td><td>${RQ.esc(a.topic==='__full__'?'Full Challenge':a.topic)}</td><td>Y${a.year}</td>
      <td><span class="chip ${a.pct>=70?'gr':a.pct>=50?'am':'rd'}">${a.score}/${a.total} (${a.pct}%)</span></td><td class="small">${new Date(a.ts).toLocaleDateString()}</td></tr>`;}).join('')
      || '<tr><td colspan="5" class="dim">No attempts yet.</td></tr>'}
  </table></div></div>`;
  const cv=host.querySelector('#ch-topics');
  if(cv && topics.length) RQ.barChart(cv, topics, topics.map(t=>Math.round(topicStats[t].sum/topicStats[t].n)), '#26d9f2');
};

/* ---------- classes ---------- */
RQ.views['t-classes'] = function(host,param,me){
  const db=RQ.DB.data;
  const myClasses=db.classes.filter(c=>c.teacherId===me.id);
  function genCode(){ const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; let c='';
    do{ c=Array.from({length:6},()=>chars[Math.floor(Math.random()*chars.length)]).join(''); }
    while(db.classes.some(x=>x.code===c)); return c; }
  host.innerHTML=`<div class="page-head"><div><div class="page-title">Class <span class="accent">Manager</span></div>
    <div class="page-sub">Create classes, share join codes, and manage enrolment. Students join with the code at registration or from their profile.</div></div></div>
  <div class="grid g23">
    <div id="cls-list">
      ${myClasses.length? myClasses.map(c=>{
        const mem=db.memberships.filter(m=>m.classId===c.id);
        return `<div class="card mb"><div class="row between"><div><h3>${RQ.esc(c.name)}</h3>
          <span class="chip cy mono" style="font-size:.95rem">JOIN CODE: ${c.code}</span> <span class="chip">${mem.length} students</span></div>
          <button class="btn danger xs" data-del="${c.id}">Delete class</button></div>
          ${mem.length? `<div class="tbl-wrap mt-s"><table class="tbl">
            <tr><th>Student</th><th>Year</th><th>XP</th><th>Joined</th><th></th></tr>
            ${mem.map(m=>{ const u=db.users.find(x=>x.id===m.studentId); if(!u) return '';
              const p=db.progress[u.id]||{stats:{xp:0}};
              return `<tr><td><b>${RQ.esc(u.name)}</b> ${u.demo?'<span class="chip">demo</span>':''}<div class="small dim">@${RQ.esc(u.username)}</div></td>
              <td><select class="speed-sel" data-year="${m.studentId}">${RQ.YEARS.map(y=>`<option value="${y}" ${u.year===y?'selected':''}>Year ${y}</option>`).join('')}</select></td>
              <td>${p.stats.xp}</td><td class="small">${new Date(m.joinedAt).toLocaleDateString()}</td>
              <td><button class="btn ghost xs" data-rm="${m.id}">Remove</button></td></tr>`;}).join('')}
          </table></div>`:'<p class="dim small mt-s">No students yet — share the join code.</p>'}
        </div>`;}).join('')
      : '<div class="empty-state"><div class="ico">👥</div><h3>No classes yet</h3><p class="muted">Create your first class to start enrolling students.</p></div>'}
    </div>
    <div>
      <div class="card"><h3>➕ Create class</h3>
        <div class="field"><label>Class name</label><input id="cls-name" placeholder="e.g. 9B Computing"></div>
        <button class="btn primary block" id="cls-create">Create & generate code</button>
        <p class="small dim mt-s">Codes are unique 6-character keys students type at registration.</p>
      </div>
      <div class="card mt"><h3>🧹 Demo data</h3>
        <p class="small dim">The leaderboard ships with clearly-marked demo students so rankings look real. Remove them once real students join.</p>
        <button class="btn warn sm" id="cls-clean">Remove all demo students</button>
      </div>
    </div>
  </div>`;
  host.querySelector('#cls-create').onclick=()=>{
    const name=host.querySelector('#cls-name').value.trim();
    if(name.length<2){ RQ.toast('Give the class a name','bad'); return; }
    db.classes.push({id:RQ.DB.uid('c'), teacherId:me.id, name, code:genCode(), createdAt:Date.now()});
    RQ.DB.save(); RQ.toast('Class created — share the join code!','good'); RQ.render();
  };
  host.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{
    RQ.confirm('Delete this class? Memberships and assignments for it will be removed (student accounts stay).', ()=>{
      const id=b.dataset.del;
      db.classes=db.classes.filter(c=>c.id!==id);
      db.memberships=db.memberships.filter(m=>m.classId!==id);
      db.assignments=db.assignments.filter(a=>a.classId!==id);
      RQ.DB.save(); RQ.render();
    });
  });
  host.querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{
    db.memberships=db.memberships.filter(m=>m.id!==b.dataset.rm);
    RQ.DB.save(); RQ.render();
  });
  host.querySelectorAll('[data-year]').forEach(sel=>sel.onchange=()=>{
    const u=db.users.find(x=>x.id===sel.dataset.year);
    if(u){ u.year=Number(sel.value); RQ.DB.save(); RQ.toast('Year group updated for '+u.name); }
  });
  const clean=host.querySelector('#cls-clean');
  if(clean) clean.onclick=()=>{
    RQ.confirm('Remove all demo students and their progress from the school?', ()=>{
      const demoIds=db.users.filter(u=>u.demo).map(u=>u.id);
      db.users=db.users.filter(u=>!u.demo);
      demoIds.forEach(id=>delete db.progress[id]);
      db.memberships=db.memberships.filter(m=>!demoIds.includes(m.studentId));
      RQ.DB.save(); RQ.render();
    });
  };
};

/* ---------- assignments ---------- */
RQ.views['t-assignments'] = function(host,param,me){
  const db=RQ.DB.data;
  const myClasses=db.classes.filter(c=>c.teacherId===me.id);
  host.innerHTML=`<div class="page-head"><div><div class="page-title">Assignments</div>
    <div class="page-sub">Assign lessons, quizzes or missions to whole classes. Assigned work appears on every member\u2019s dashboard — assigned lessons override the usual unlock order.</div></div></div>
  ${myClasses.length? `
  <div class="card"><h3>➕ New assignment</h3>
    <div class="grid g4 mt-s">
      <div class="field"><label>Class</label><select id="as-class">${myClasses.map(c=>`<option value="${c.id}">${RQ.esc(c.name)}</option>`).join('')}</select></div>
      <div class="field"><label>Type</label><select id="as-kind"><option value="lesson">📘 Lesson</option><option value="quiz">⚔️ Quiz topic</option><option value="mission">🤖 Mission</option></select></div>
      <div class="field"><label>Item</label><select id="as-item"></select></div>
      <div class="field"><label>&nbsp;</label><button class="btn primary block" id="as-create">Assign</button></div>
    </div></div>` : '<div class="empty-state"><div class="ico">📋</div>Create a class first to assign work.</div>'}
  <div class="card mt"><h3>📋 Current assignments</h3><div class="tbl-wrap"><table class="tbl">
    <tr><th>Class</th><th>Type</th><th>Item</th><th>Assigned</th><th></th></tr>
    ${db.assignments.filter(a=>myClasses.some(c=>c.id===a.classId)).map(a=>{
      const c=db.classes.find(x=>x.id===a.classId);
      return `<tr><td>${RQ.esc(c?c.name:'?')}</td><td><span class="chip">${a.kind}</span></td><td><b>${RQ.esc(a.title)}</b></td>
      <td class="small">${new Date(a.ts).toLocaleDateString()}</td><td><button class="btn ghost xs" data-del="${a.id}">Remove</button></td></tr>`;}).join('')
      || '<tr><td colspan="5" class="dim">Nothing assigned yet.</td></tr>'}
  </table></div></div>`;
  if(myClasses.length){
    const kindSel=host.querySelector('#as-kind'), itemSel=host.querySelector('#as-item');
    function fillItems(){
      const k=kindSel.value;
      if(k==='lesson'){ const me2=me; const ys=RQ.YEARS;
        itemSel.innerHTML=ys.map(y=>`<optgroup label="Year ${y}">`+RQ.lessonsFor(y).map(l=>`<option value="${l.id}" data-y="${y}">${RQ.esc(l.title)}</option>`).join('')+'</optgroup>').join(''); }
      else if(k==='mission'){ itemSel.innerHTML=RQ.DATA.MISSIONS.map(m=>`<option value="${m.id}" data-y="${m.year}">${RQ.esc(m.title)} (Y${m.year})</option>`).join(''); }
      else { itemSel.innerHTML=RQ.YEARS.map(y=>`<optgroup label="Year ${y}">`+RQ.quizTopics(y).map(t=>`<option value="${t}" data-y="${y}">${RQ.esc(t)} quiz (Y${y})</option>`).join('')+'</optgroup>').join(''); }
    }
    fillItems(); kindSel.onchange=fillItems;
    host.querySelector('#as-create').onclick=()=>{
      const classId=host.querySelector('#as-class').value, kind=kindSel.value;
      const opt=itemSel.selectedOptions[0];
      const refId=opt.value, y=Number(opt.dataset.y);
      let title;
      if(kind==='lesson'){ const l=RQ.lessonById(refId); title=l? l.title : refId; }
      else if(kind==='mission'){ const m=RQ.missionById(refId); title=m? m.title : refId; }
      else title=refId+' quiz (Y'+y+')';
      db.assignments.push({id:RQ.DB.uid('a'), classId, kind, refId, title, year:y, ts:Date.now()});
      RQ.DB.save(); RQ.toast('Assigned to class — students will see it on their dashboards','good'); RQ.render();
    };
    host.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{
      db.assignments=db.assignments.filter(a=>a.id!==b.dataset.del);
      RQ.DB.save(); RQ.render();
    });
  }
};

/* ---------- reports ---------- */
RQ.views['t-reports'] = function(host,param,me){
  const db=RQ.DB.data;
  const students=db.users.filter(u=>u.role==='student').sort((a,b)=>a.name.localeCompare(b.name));
  let selected=students[0]?students[0].id:null;
  function render(){
    const u=students.find(s=>s.id===selected);
    const p=u?db.progress[u.id]:null;
    const ls=u?RQ.lessonsForStudent(u):[];
    const lessonsDone=ls.filter(l=>p&&p.lessons[l.id]&&p.lessons[l.id].done);
    const missions=RQ.missionsFor(u?u.year:0);
    const mDone=missions.filter(m=>p&&p.missions[m.id]&&p.missions[m.id].done);
    const attempts=db.quizAttempts.filter(a=>a.uid===selected).slice(-10).reverse();
    const mAtt=db.missionAttempts.filter(a=>a.uid===selected).slice(-10).reverse();
    const inClass=selected && RQ.isTeacherOf(me, selected);
    host.innerHTML=`<div class="page-head"><div><div class="page-title">Student <span class="accent">Reports</span></div>
      <div class="page-sub">Individual learning reports and class performance. ${students.length} students enrolled.</div></div></div>
    <div class="sim-layout" style="grid-template-columns:300px 1fr">
      <div class="card"><h3>🎓 Students</h3><div style="max-height:520px;overflow:auto">
        ${students.map(s=>{ const pp=db.progress[s.id]||{stats:{xp:0}};
          return `<div class="row between" style="border-bottom:1px dashed var(--line);padding:8px 0;cursor:pointer" data-sel="${s.id}" style="${s.id===selected?'':''}">
          <span class="small ${s.id===selected?'glow-cy':''}">${RQ.esc(s.name)} <span class="dim">Y${s.year}</span></span>
          <span class="chip cy">${pp.stats.xp} XP</span></div>`;}).join('')}
      </div></div>
      <div>${!u? '<div class="empty-state">No students yet.</div>' : `
        <div class="card"><div class="row between"><div><h3>${RQ.esc(u.name)} <span class="chip pu">Year ${u.year}</span>${u.demo?' <span class="chip">demo</span>':''}</h3>
          <div class="small dim">@${RQ.esc(u.username)} · Level ${RQ.Game.levelOf(p.stats.xp).lvl} · ${p.stats.xp} XP · ${p.stats.coins} coins · streak ${p.streak.count}</div></div>
          ${inClass? `<div class="row"><select class="speed-sel" id="rp-year">${RQ.YEARS.map(y=>`<option value="${y}" ${u.year===y?'selected':''}>Year ${y}</option>`).join('')}</select>
          <button class="btn danger xs" id="rp-reset">Reset progress</button></div>`
          : '<span class="chip">not in your classes</span>'}</div>
          <div class="grid g4 mt-s">
            <div class="card center" style="padding:10px"><div class="stat-num" style="font-size:1.2rem">${lessonsDone.length}/${ls.length}</div><div class="stat-lbl">Lessons</div></div>
            <div class="card center" style="padding:10px"><div class="stat-num" style="font-size:1.2rem">${mDone.length}/${missions.length}</div><div class="stat-lbl">Missions</div></div>
            <div class="card center" style="padding:10px"><div class="stat-num" style="font-size:1.2rem">${classAvgQuiz(db,[u.id])===null?'—':classAvgQuiz(db,[u.id])+'%'}</div><div class="stat-lbl">Avg quiz</div></div>
            <div class="card center" style="padding:10px"><div class="stat-num" style="font-size:1.2rem">${p.badges.length}</div><div class="stat-lbl">Badges</div></div>
          </div>
        </div>
        <div class="grid g2 mt">
          <div class="card"><h3>📘 Lesson progress</h3>
            ${ls.map(l=>{ const lr=p.lessons[l.id]||{};
              return `<div class="row between" style="border-bottom:1px dashed var(--line);padding:6px 0">
              <span class="small">${RQ.esc(l.title)}</span>
              <span class="chip ${lr.done?'gr':''}">${lr.done?'complete':(lr.step?'step '+lr.step+'/7':'not started')}</span></div>`;}).join('')}
          </div>
          <div class="card"><h3>🤖 Mission performance</h3>
            ${missions.map(m=>{ const mr=p.missions[m.id]||{};
              return `<div class="row between" style="border-bottom:1px dashed var(--line);padding:6px 0">
              <span class="small">${RQ.esc(m.title)}</span>
              <span class="chip ${mr.done?'gr':'dim'}">${mr.done? '★'.repeat(mr.stars||0) : (mAtt.some(a=>a.mid===m.id)?'attempted':'—')}</span></div>`;}).join('')}
          </div>
        </div>
        <div class="grid g2 mt">
          <div class="card"><h3>⚔️ Quiz attempts</h3>
            ${attempts.length? `<div class="tbl-wrap"><table class="tbl"><tr><th>Quiz</th><th>Score</th><th>When</th></tr>
              ${attempts.map(a=>`<tr><td>${RQ.esc(a.topic==='__full__'?'Full Challenge':a.topic)}</td><td><span class="chip ${a.pct>=70?'gr':a.pct>=50?'am':'rd'}">${a.score}/${a.total}</span></td><td class="small">${new Date(a.ts).toLocaleDateString()}</td></tr>`).join('')}</table></div>`
              : '<p class="dim small">No quizzes taken yet.</p>'}
          </div>
          <div class="card"><h3>🏅 Badges</h3><div class="row">
            ${p.badges.length? p.badges.map(b=>{ const d=RQ.Game.badgeDefs(u).find(x=>x.id===b);
              return `<span class="chip pu" title="${d?RQ.esc(d.desc):''}">${d?d.icon+' '+RQ.esc(d.name):b}</span>`; }).join('')
              : '<span class="dim small">None earned yet.</span>'}</div>
            <p class="small dim mt-s">Coding runs: ${p.stats.codeRuns} code lab runs · ${p.stats.blockRuns} block programs · ${p.stats.pyRuns} Python programs · ${p.stats.dailyDone} daily challenges</p>
          </div>
        </div>`}</div>
    </div>`;
    host.querySelectorAll('[data-sel]').forEach(el=>el.onclick=()=>{ selected=el.dataset.sel; render(); });
    const ys=host.querySelector('#rp-year');
    if(ys) ys.onchange=()=>{ u.year=Number(ys.value); RQ.DB.save(); RQ.toast('Year group changed to Year '+u.year); render(); };
    const rs=host.querySelector('#rp-reset');
    if(rs) rs.onclick=()=>{ RQ.confirm('Reset ALL progress for '+u.name+'? XP, coins, lessons, missions and badges return to zero. This cannot be undone.', ()=>{
      db.progress[u.id]=RQ.newProgress(); RQ.DB.save(); RQ.toast('Progress reset','good'); render(); }); };
  }
  render();
};

/* ---------- content studio ---------- */
RQ.views['t-content'] = function(host,param,me){
  const db=RQ.DB.data;
  let tab='question';
  const painter={cols:12, rows:8, cells:{}, start:null, dir:'E'};
  const TILE_CYCLE=['.','#','E','T','C','L','l','X','P','B','D','~','O'];
  function render(){
    host.innerHTML=`<div class="page-head"><div><div class="page-title">Content <span class="accent">Studio</span></div>
      <div class="page-sub">Extend the curriculum: custom questions, lessons, Python challenges and robot missions. Everything you create appears immediately in the student platform for the chosen year.</div></div></div>
    <div class="tabs">
      ${[['question','❓ Question'],['lesson','📘 Lesson'],['challenge','🐍 Python challenge'],['mission','🤖 Robot mission']].map(t=>`<span class="tab ${tab===t[0]?'on':''}" data-t="${t[0]}">${t[1]}</span>`).join('')}
    </div>
    <div id="cs-body"></div>
    <div class="card mt"><h3>📚 Custom content created</h3><div class="row mt-s">
      <span class="chip">${db.customQuestions.length} questions</span><span class="chip">${db.customLessons.length} lessons</span>
      <span class="chip">${db.customChallenges.length} python challenges</span><span class="chip">${db.customMissions.length} missions</span>
    </div>
    ${db.customQuestions.length? '<div class="tbl-wrap mt-s"><table class="tbl"><tr><th>Question</th><th>Year</th><th>Topic</th><th></th></tr>'
      +db.customQuestions.map(q=>`<tr><td>${RQ.esc(q.q)}</td><td>Y${q.year}</td><td>${RQ.esc(q.topic)}</td><td><button class="btn ghost xs" data-delq="${q.id}">Delete</button></td></tr>`).join('')+'</table></div>':''}
    ${db.customMissions.length? '<div class="tbl-wrap mt-s"><table class="tbl"><tr><th>Mission</th><th>Year</th><th>XP</th><th></th></tr>'
      +db.customMissions.map(m=>`<tr><td>${RQ.esc(m.title)}</td><td>Y${m.year}</td><td>${m.xp}</td><td><button class="btn ghost xs" data-delm="${m.id}">Delete</button></td></tr>`).join('')+'</table></div>':''}
    </div>`;
    host.querySelectorAll('.tab[data-t]').forEach(t=>t.onclick=()=>{ tab=t.dataset.t; render(); });
    host.querySelectorAll('[data-delq]').forEach(b=>b.onclick=()=>{
      db.customQuestions=db.customQuestions.filter(q=>q.id!==b.dataset.delq); RQ.DB.save(); render(); });
    host.querySelectorAll('[data-delm]').forEach(b=>b.onclick=()=>{
      db.customMissions=db.customMissions.filter(m=>m.id!==b.dataset.delm); RQ.DB.save(); render(); });
    if(tab==='question') renderQuestion();
    if(tab==='lesson') renderLesson();
    if(tab==='challenge') renderChallenge();
    if(tab==='mission') renderMission();
  }
  function renderQuestion(){
    const el=host.querySelector('#cs-body');
    el.innerHTML=`<div class="card"><h3>❓ Add a quiz question</h3>
      <div class="grid g3 mt-s">
        <div class="field"><label>Year group</label><select id="cq-year">${RQ.YEARS.map(y=>`<option value="${y}">Year ${y}</option>`).join('')}</select></div>
        <div class="field"><label>Topic</label><input id="cq-topic" placeholder="e.g. Loops"></div>
        <div class="field"><label>Type</label><select id="cq-type"><option value="mc">Multiple choice</option><option value="tf">True / false</option></select></div>
      </div>
      <div class="field"><label>Question</label><textarea id="cq-q" placeholder="Ask something meaningful — problem-solving beats memorisation"></textarea></div>
      <div id="cq-opts">
        <div class="grid g3">${[0,1,2,3].map(i=>`<div class="field"><label>Option ${'ABCD'[i]} ${i===0?'(correct)':''}</label><input id="cq-o${i}"></div>`).join('')}</div>
        <div class="field"><label>Correct option</label><select id="cq-a"><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></div>
      </div>
      <div id="cq-tf" style="display:none"><div class="field"><label>Correct answer</label><select id="cq-tf-a"><option value="0">TRUE</option><option value="1">FALSE</option></select></div></div>
      <div class="field"><label>Explanation (shown after answering)</label><input id="cq-e"></div>
      <button class="btn primary" id="cq-save">Save question</button></div>`;
    host.querySelector('#cq-type').onchange=e=>{
      const tf=e.target.value==='tf';
      host.querySelector('#cq-opts').style.display=tf?'none':'block';
      host.querySelector('#cq-tf').style.display=tf?'block':'none';
    };
    host.querySelector('#cq-save').onclick=()=>{
      const year=Number(host.querySelector('#cq-year').value);
      const topic=host.querySelector('#cq-topic').value.trim()||'Teacher questions';
      const type=host.querySelector('#cq-type').value;
      const q=host.querySelector('#cq-q').value.trim();
      const e=host.querySelector('#cq-e').value.trim();
      if(q.length<5){ RQ.toast('Write the question first','bad'); return; }
      if(type==='tf'){
        db.customQuestions.push({id:RQ.DB.uid('cq'), year, topic, type:'tf', q, a:Number(host.querySelector('#cq-tf-a').value), e, by:me.name});
      } else {
        const o=[0,1,2,3].map(i=>host.querySelector('#cq-o'+i).value.trim());
        if(o.filter(Boolean).length<2){ RQ.toast('Provide at least two options','bad'); return; }
        const os=o.filter(Boolean);
        let a=Number(host.querySelector('#cq-a').value);
        // re-map: if some option blank and answer beyond, shift
        if(o[a]==='' || a>=os.length){ a=Math.min(a, os.length-1); }
        db.customQuestions.push({id:RQ.DB.uid('cq'), year, topic, type:'mc', q, o:os, a, e, by:me.name});
      }
      RQ.DB.save(); RQ.toast('Question saved — students see it in the arena now','good'); render();
    };
  }
  function renderLesson(){
    const el=host.querySelector('#cs-body');
    el.innerHTML=`<div class="card"><h3>📘 Add a teacher lesson</h3>
      <div class="grid g3 mt-s">
        <div class="field"><label>Year group</label><select id="cl-year">${RQ.YEARS.map(y=>`<option value="${y}">Year ${y}</option>`).join('')}</select></div>
        <div class="field"><label>Title</label><input id="cl-title" placeholder="e.g. Introduction to Spreadsheets"></div>
        <div class="field"><label>Unit name</label><input id="cl-unit" placeholder="e.g. Teacher Lessons"></div>
      </div>
      <div class="field"><label>Learning objectives (one per line)</label><textarea id="cl-obj" placeholder="Explain...&#10;Apply...&#10;Evaluate..."></textarea></div>
      <div class="field"><label>Lesson body (paragraphs separated by blank lines)</label><textarea id="cl-body" style="min-height:140px"></textarea></div>
      <div class="field"><label>Example code (optional, shown in step 3)</label><textarea id="cl-code">print("example")</textarea></div>
      <div class="field"><label>Summary points (one per line)</label><textarea id="cl-sum"></textarea></div>
      <div class="row"><div class="field" style="flex:1"><label>XP reward</label><input id="cl-xp" type="number" value="40"></div>
      <div class="field" style="flex:2"><label>&nbsp;</label><button class="btn primary block" id="cl-save">Save lesson</button></div></div>
      <p class="small dim">Teacher lessons appear in the Academy for that year group as "🧑‍🏫 Teacher Lessons" and are always unlocked.</p></div>`;
    host.querySelector('#cl-save').onclick=()=>{
      const title=host.querySelector('#cl-title').value.trim();
      const body=host.querySelector('#cl-body').value.trim();
      if(title.length<3||body.length<30){ RQ.toast('Lesson needs a title and a real body (30+ chars)','bad'); return; }
      db.customLessons.push({id:RQ.DB.uid('cl'), year:Number(host.querySelector('#cl-year').value), title,
        unit:host.querySelector('#cl-unit').value.trim()||'Teacher Lessons',
        objectives:host.querySelector('#cl-obj').value.split('\n').map(s=>s.trim()).filter(Boolean),
        body, example:host.querySelector('#cl-code').value,
        summary:host.querySelector('#cl-sum').value.split('\n').map(s=>s.trim()).filter(Boolean),
        xp:Number(host.querySelector('#cl-xp').value)||40, by:me.name, ts:Date.now()});
      RQ.DB.save(); RQ.toast('Lesson published to the Academy','good'); render();
    };
  }
  function renderChallenge(){
    const el=host.querySelector('#cs-body');
    el.innerHTML=`<div class="card"><h3>🐍 Add a Python challenge</h3>
      <div class="grid g3 mt-s">
        <div class="field"><label>Year group</label><select id="cc-year">${RQ.YEARS.map(y=>`<option value="${y}">Year ${y}</option>`).join('')}</select></div>
        <div class="field"><label>Title</label><input id="cc-title"></div>
        <div class="field"><label>XP</label><input id="cc-xp" type="number" value="40"></div>
      </div>
      <div class="field"><label>Brief / instructions</label><textarea id="cc-brief"></textarea></div>
      <div class="field"><label>Starter code</label><textarea id="cc-starter"># starter\n</textarea></div>
      <div class="field"><label>Expected output lines (one per line, exact)</label><textarea id="cc-expect" placeholder="line1&#10;line2"></textarea></div>
      <div class="field"><label>Example solution</label><textarea id="cc-sol"></textarea></div>
      <button class="btn primary" id="cc-save">Save challenge</button>
      <p class="small dim mt-s">The student\u2019s printed output must match your expected lines (trimmed). Test your own solution with the simulator before saving.</p></div>`;
    host.querySelector('#cc-save').onclick=()=>{
      const title=host.querySelector('#cc-title').value.trim();
      const expect=host.querySelector('#cc-expect').value.split('\n').map(s=>s.trim()).filter(Boolean);
      const sol=host.querySelector('#cc-sol').value;
      if(title.length<3||!expect.length||!sol.trim()){ RQ.toast('Title, expected output and solution are required','bad'); return; }
      try{ const out=runLessonPy(sol).map(s=>String(s).replace(/\r/g,'').trim());
        if(JSON.stringify(out)!==JSON.stringify(expect)) throw new Error('Your solution prints: '+(out.join(' | ')||'(nothing)')+' — expected: '+expect.join(' | '));
      }catch(e){ RQ.toast('Solution check failed: '+e.message,'bad'); return; }
      db.customChallenges.push({id:RQ.DB.uid('cc'), year:Number(host.querySelector('#cc-year').value), title,
        brief:host.querySelector('#cc-brief').value.trim(), starter:host.querySelector('#cc-starter').value,
        expect, solution:sol, xp:Number(host.querySelector('#cc-xp').value)||40, custom:true, ts:Date.now()});
      RQ.DB.save(); RQ.toast('Challenge published and auto-verified','good'); render();
    };
  }
  function renderMission(){
    const el=host.querySelector('#cs-body');
    const ICONS={'.':'⬜ floor','#':'🧱 wall','E':'⚡ energy','T':'◎ target','C':'⚡ charge','L':'💡 light','l':'🛤 line','X':'📦 parcel','P':'🟣 drop pad','B':'🟢 button','D':'🚪 door','~':'🌊 water','O':'📦 crate'};
    el.innerHTML=`<div class="card"><h3>🤖 Build a robot mission</h3>
      <div class="grid g3 mt-s">
        <div class="field"><label>Title</label><input id="cm-title"></div>
        <div class="field"><label>Year group</label><select id="cm-year">${RQ.YEARS.map(y=>`<option value="${y}">Year ${y}</option>`).join('')}</select></div>
        <div class="field"><label>Objective</label><select id="cm-obj"><option value="reach">Reach the target</option><option value="collect_reach">Collect all energy, then target</option><option value="deliver">Deliver all parcels to P</option></select></div>
      </div>
      <div class="grid g3">
        <div class="field"><label>XP reward</label><input id="cm-xp" type="number" value="120"></div>
        <div class="field"><label>Par moves (for 3★)</label><input id="cm-par" type="number" value="20"></div>
        <div class="field"><label>Brief text</label><input id="cm-brief" placeholder="What the robot must do"></div>
      </div>
      <p class="small dim">Paint the grid by clicking cells (cycles tile types). Set the robot start, then save.</p>
      <div id="paint-grid" class="mb-s" style="display:grid;grid-template-columns:repeat(${painter.cols},1fr);gap:2px;max-width:640px">
        ${Array.from({length:painter.rows*painter.cols},(_,i)=>{
          const x=i%painter.cols, y=Math.floor(i/painter.cols);
          const c=painter.cells[x+','+y]||'.';
          return `<div data-x="${x}" data-y="${y}" title="${x},${y}" style="aspect-ratio:1;display:grid;place-items:center;font-size:.75rem;background:${c==='#'?'#1c2748':c==='.'?'#0a1128':'rgba(79,124,255,.15)'};border:1px solid var(--line);border-radius:4px;cursor:pointer">${painter.start&&painter.start.x===x&&painter.start.y===y?'🤖':ICONS[c]}</div>`;
        }).join('')}
      </div>
      <div class="row"><span class="small dim">Start:</span>
        <select class="speed-sel" id="cm-sx">${Array.from({length:painter.cols},(_,i)=>`<option value="${i}">x${i}</option>`).join('')}</select>
        <select class="speed-sel" id="cm-sy">${Array.from({length:painter.rows},(_,i)=>`<option value="${i}">y${i}</option>`).join('')}</select>
        <select class="speed-sel" id="cm-dir">${['E','S','W','N'].map(d=>`<option ${d===painter.dir?'selected':''}>${d}</option>`).join('')}</select>
        <span class="sp"></span><button class="btn primary" id="cm-save">Save mission</button></div></div>`;
    el.querySelectorAll('#paint-grid div[data-x]').forEach(cell=>cell.onclick=()=>{
      const x=cell.dataset.x, y=cell.dataset.y;
      const cur=painter.cells[x+','+y]||'.';
      const next=TILE_CYCLE[(TILE_CYCLE.indexOf(cur)+1)%TILE_CYCLE.length];
      painter.cells[x+','+y]=next; render();
    });
    host.querySelector('#cm-save').onclick=()=>{
      const title=host.querySelector('#cm-title').value.trim();
      if(title.length<3){ RQ.toast('Give the mission a title','bad'); return; }
      const sx=Number(host.querySelector('#cm-sx').value), sy=Number(host.querySelector('#cm-sy').value);
      const dir=host.querySelector('#cm-dir').value; painter.dir=dir;
      const grid=Array.from({length:painter.rows},(_,y)=>Array.from({length:painter.cols},(_,x)=>{
        const isStart= sx===x && sy===y;
        return isStart? 'R' : (painter.cells[x+','+y]||'.');
      }).join(''));
      // border safety: force outer walls
      for(let x=0;x<painter.cols;x++){ if(grid[0][x]!=='R') grid[0]=grid[0].substring(0,x)+'#'+grid[0].substring(x+1); if(grid[painter.rows-1][x]!=='R') grid[painter.rows-1]=grid[painter.rows-1].substring(0,x)+'#'+grid[painter.rows-1].substring(x+1); }
      for(let y=0;y<painter.rows;y++){ if(grid[y][0]!=='R') grid[y]='#'+grid[y].substring(1); if(grid[y][painter.cols-1]!=='R') grid[y]=grid[y].substring(0,painter.cols-1)+'#'; }
      const obj=host.querySelector('#cm-obj').value;
      const tset=new Set(grid.join('').split(''));
      if(!tset.has('R')){ RQ.toast('Pick a start cell (set start x/y — it overwrites the tile)','bad'); return; }
      if(obj!=='deliver' && !tset.has('T')){ RQ.toast('Paint at least one target (T) for this objective','bad'); return; }
      if(obj==='collect_reach' && !tset.has('E')){ RQ.toast('Paint at least one energy cell (E)','bad'); return; }
      if(obj==='deliver' && !(tset.has('X')&&tset.has('P'))){ RQ.toast('Deliver objective needs parcels (X) and a drop pad (P)','bad'); return; }
      db.customMissions.push({id:RQ.DB.uid('cm'), custom:true, year:Number(host.querySelector('#cm-year').value), title,
        brief:host.querySelector('#cm-brief').value.trim()||'Teacher-built mission',
        instructions:['Follow the briefing and complete the objective.','Use sensors to avoid collisions.'], objective:{type:obj},
        grid, startDir:dir, xp:Number(host.querySelector('#cm-xp').value)||120, par:Number(host.querySelector('#cm-par').value)||20,
        hints:['Trace your route on paper first.','Check the sensor HUD after each run.'],
        explain:'Teacher mission complete — well flown, engineer.', lang:'dsl', allowBlocks:true, ts:Date.now()});
      RQ.DB.save(); RQ.toast('Mission published to the mission map','good'); render();
    };
  }
  render();
};

/* ---------- settings ---------- */
RQ.views['t-settings'] = function(host,param,me){
  const db=RQ.DB.data;
  host.innerHTML=`<div class="page-head"><div><div class="page-title">Platform <span class="accent">Settings</span></div>
    <div class="page-sub">School-wide options and data controls.</div></div></div>
  <div class="grid g2">
    <div class="card"><h3>🏆 Leaderboard visibility</h3>
      <label class="row mt-s" style="cursor:pointer"><input type="checkbox" id="s-pub" ${db.settings.leaderboardPublic?'checked':''} style="accent-color:#26d9f2">
      <span>Show public rankings to students (whole school + year groups)</span></label>
      <p class="small dim mt-s">When disabled, students see only their own position. Teachers always see full rankings.</p>
      <button class="btn primary sm mt-s" id="s-save">Save setting</button>
    </div>
    <div class="card"><h3>🔐 Teacher registration</h3>
      <p class="small dim">New teachers join with the invite code. Share it only with staff.</p>
      <div class="codeblock mt-s"><pre id="s-invite">${RQ.TEACHER_INVITE_CODE}</pre></div>
      <button class="btn ghost sm mt-s" id="s-reveal">Reveal / hide code</button>
    </div>
    <div class="card"><h3>💾 Data (Local Mode)</h3>
      <p class="small dim">All school data lives in this browser. Export regular backups; import them on any device to restore.</p>
      <div class="row mt-s"><button class="btn ghost sm" id="s-export">⬇ Export school backup</button>
      <button class="btn ghost sm" id="s-import">⬆ Import backup</button>
      <input type="file" id="s-file" accept=".json" style="display:none"></div>
    </div>
    <div class="card"><h3>ℹ️ About</h3>
      <p class="small muted">ROBOQUEST v1.0 — Code. Think. Build. Conquer.<br>
      4 year pathways · ${RQ.YEARS.reduce((s,y)=>s+RQ.lessonsFor(y).length,0)} lessons · ${RQ.DATA.QUESTIONS.length} quiz questions · ${RQ.DATA.MISSIONS.length} robot missions · complete XP/achievement system.<br>
      <span class="dim">Runs fully client-side: no server, no external services, student data never leaves the device.</span></p>
    </div>
  </div>`;
  host.querySelector('#s-save').onclick=()=>{ db.settings.leaderboardPublic=host.querySelector('#s-pub').checked; RQ.DB.save(); RQ.toast('Setting saved','good'); };
  host.querySelector('#s-reveal').onclick=()=>{ const el=host.querySelector('#s-invite'); el.style.visibility=el.style.visibility==='hidden'?'visible':'hidden'; };
  host.querySelector('#s-export').onclick=()=>RQ.DB.export();
  host.querySelector('#s-import').onclick=()=>host.querySelector('#s-file').click();
  host.querySelector('#s-file').onchange=e=>{ const f=e.target.files[0]; if(!f) return;
    RQ.DB.import(f, err=>{ if(err) RQ.toast('Import failed: '+err,'bad'); else { RQ.toast('School data imported','good'); RQ.render(); } }); };
};
